window.DC_DATA.hb=[{"id":"hb-intro","title":"تمهيد","from":8,"to":11,"b":[{"k":"page","p":8},{"k":"h2","t":"تمهيد"},{"k":"p","t":"عزيزي المتدرب، مرحبا بك في تجربة رخصة القيادة التي قمنا بإعدادها خصيصا لك بهدف مساعدتك في الحصول على رخصة قيادة في المملكة العربية السعودية. في البداية نود أن نؤكد أن قيادة المركبة هو امتياز ومسؤولية هامة للسائق، في الوقت الحالي أكثر من أي وقت مضى و من المهم للغاية للسائق تطوير مهارات قيادة وقائية، بمعنى ليس فقط تجنب الأمور التي تلهيه وتربكه داخل المركبة، لكن أيضا البقاء متيقظ ، وأن يتجنب أخطاء مستخدمي الطريق، لأن عدم القيام بذلك قد يؤدي إلى عواقب مأساوية.","b":true},{"k":"p","t":"يهدف هذا الكتيب إلى مساعدتك للقيادة بأمان وإعدادك لاختبار القيادة بشقيه العملي والنظري من خلال إرشادك في الجلسات النظرية وتوجيهك خلال الجزء النظري للحصول على رخصة قيادة خاصة بك، ويحتوي على معلومات قد جرى التعامل معها بنفس تسلسل المعلومات الواردة في الدروس النظرية لكن بمزيد من التفصيل والإيضاح. قمنا أيضا في بعض الوحدات بتضمين معلومات إضافية حول المواضيع ذات العلاقة لاستخدامك الشخصي، وقد تم وضع علامات على هذه المعلومات الإضافية باللون الأزرق ولن يتم تضمينها في قسم المعرفة في اختبار رخصة القيادة. من المفترض أن يستخدم هذا الكتيب ليس كمرجع فقط ولكن أيضا كدليل عملي، و مع توفر مساحة إضافية لتدوين الملاحظات. كلنا ثقة أن هذه الأدوات ستساعدك على الاستعداد بشكل أفضل لاختبار القيادة ونأمل منك استخدامها بالشكل المناسب.","b":false},{"k":"p","t":"بمجرد حصولك على رخصة القيادة، نقترح عليك الاحتفاظ بهذا الكتيب كمرجع حول السلامة المرورية وتحديثه حسب الحاجة.","b":false},{"k":"p","t":"يرجى منك مراجعة المعلومات الواردة في هذا الكتيب ودراستها بعناية، وأن تضع دائما نصب عينيك المسؤولية الكبيرة المناطة بك بعد حصولك على رخصة قيادة في المملكة العربية السعودية وخارجها.","b":false},{"k":"p","t":"مع أطيب التحيات، الإدارة العامة للمرور","b":false},{"k":"page","p":9},{"k":"h2","t":"“مرحبا، دوري هو توجيهك خلال الدورة التدريبية!”"},{"k":"page","p":10},{"k":"h2","t":"الوحدة الأولى المقدمة والمخالفات المرورية"},{"k":"h2","t":"والنقاط المرورية"},{"k":"page","p":11}]},{"id":"hb-licence","title":"رخصة القيادة","from":12,"to":15,"b":[{"k":"page","p":12},{"k":"h2","t":"1. رخصة القيادة"},{"k":"h3","t":"رخصة قيادة خاصة"},{"k":"p","t":"يجب عليك استيفاء المتطلبات التالية للحصول على رخصة قيادة خاصة:","b":true},{"k":"li","t":"أن لا يقل عمرك عن 18 عاما (استثناءات: تصريح مؤقت لمدة أقصاها سنة واحدة يمكن منحه إذا أتم سن السابعة عشر)","b":false},{"k":"li","t":"إكمال التدريب المطلوب في مدارس تعليم قيادة المركبات","b":false},{"k":"li","t":"اجتياز الاختبار النظري واختبار القيادة العملي","b":false},{"k":"li","t":"دفع الرسوم المقررة","b":false},{"k":"li","t":"تسديد المخالفات المرورية المترتبة على مخالفات سابقة، إن وجدت","b":false},{"k":"p","t":"رخصة القيادة الخاصة صالحة وتؤهلك لما يلي:","b":true},{"k":"li","t":"رخصة قيادتك الخاصة صالحة لمدة 10 سنوات كحد أقصى","b":false},{"k":"li","t":"يمكنك نقل 9 أشخاص كحد أقصى، بما في ذلك السائق","b":false},{"k":"li","t":"يمكنك قيادة جميع أنواع المركبات الخاصة الصغيرة","b":false},{"k":"li","t":"يمكنك تشغيل المركبات التي لا يزيد وزنها عن 3500 كغم كحد أقصى.","b":false},{"k":"page","p":13},{"k":"p","t":"تحتوي رخصة القيادة الخاصة بك على المعلومات التالية:","b":true},{"k":"li","t":"الاسم الكامل لحامل الرخصة","b":false},{"k":"li","t":"رقم الهوية الوطنية/ هوية مقيم","b":false},{"k":"li","t":"تاريخ الميلاد","b":false},{"k":"li","t":"القيود","b":false},{"k":"li","t":"نوع الرخصة","b":false},{"k":"li","t":"فصيلة الدم","b":false},{"k":"li","t":"تاريخ الإصدار","b":false},{"k":"li","t":"تاريخ الإنتهاء","b":false},{"k":"li","t":"الجنسية","b":false},{"k":"page","p":14},{"k":"h3","t":"رخصة قيادة عامة"},{"k":"p","t":"متطلبات رخصة القيادة العامة وصلاحيتها","b":true},{"k":"li","t":"يجب ألا يقل عمرك عن 20 عاما للحصول على رخصة قيادة عامة","b":false},{"k":"li","t":"رخصة القيادة العامة صالحة لمدة 5 سنوات كحد أقصى","b":false},{"k":"p","t":"هناك 3 أنواع مختلفة من رخصة القيادة العامة","b":true},{"k":"li","t":"الفئة 1 – رخصة قيادة مركبة أجرة تسمح لحاملها بقيادة مركبات الأجرة العامة التي لا تتجاوز حمولتها ثمانية أشخاص","b":false},{"k":"li","t":"الفئة 2 – رخصة النقل تسمح رخصة النقل الخفيف لحاملها بقيادة وسائل النقل العام الصغيرة التي لا يزيد وزنها الإجمالي عن (3500) كغم. تسمح رخصة النقل الثقيل لحاملها بقيادة مركبات نقل كبيرة عامة أو خاصة يزيد وزنها الإجمالي عن (3500) كغم.","b":false},{"k":"li","t":"الفئة 3 – الحافلات رخصة حافلة صغيرة أو خاصة تسمح لحاملها بقيادة الحافلات التي يمكنها نقل ما لا يقل عن 15 راكب . رخصة حافلة كبيرة أو عامة تسمح لحاملها بقيادة الحافلات التي يمكنها نقل أكثر من 15 راكب .","b":false},{"k":"page","p":15},{"k":"h3","t":"رخصة قيادة مركبات اشغال عامة"},{"k":"p","t":"متطلبات رخصة قيادة مركبات اشغال عامة وصلاحيتها","b":true},{"k":"li","t":"يجب أن يكون عمرك 20 عاما على الأقل للحصول على رخصة قيادة لمركبات اشغال عامة.","b":false},{"k":"li","t":"رخصة القيادة لمركبات اشغال عامة صالحة لمدة 5 سنوات كحد أقصى.","b":false},{"k":"li","t":"أ لا يكون طالب رخصة القيادة العامة، ورخصة قيادة مركبات الأشغال العامة، قد سبق الحكم عليه قضائيا في جريمة اعتداء على النفس، أو العرض، أو المال، ما لم يكن قد رد إليه اعتباره.","b":false},{"k":"li","t":"ألا يكون طالب الرخصة - مهما كان نوعها - قد أدين بحكم قضائي بتعاطي المخدرات أو صنعها، أو تهريبها، أو ترويجها، أو حيازتها، ما لم يكن قد رد إليه اعتباره.","b":false},{"k":"li","t":"الإقامة النظامية لغير السعوديين.","b":false},{"k":"li","t":"السلامة من الأمراض و العاهات التي تمنع من قيادة المركبة المرخص قيادتها.","b":false},{"k":"li","t":"إتمام ساعات تدريبية في مدارس تعليم قيادة المركبات، واجتياز اختبار القيادة، و تحدد اللائحة عدد الساعات التدريبية اللازمة، والاختبار الخاص بكل رخصة، وشرط أدائه.","b":false},{"k":"li","t":"دفع الرسوم المقرره.","b":false},{"k":"li","t":"تسديد الغرامات المرورية المترتبة على مخالفات سابقة، إن وجدت.","b":false},{"k":"h3","t":"رخصة قيادة دراجة نارية"},{"k":"p","t":"متطلبات رخصة قيادة الدراجة الآلية","b":true},{"k":"li","t":"صالحة لكافة أنواع الدراجات الآلية.","b":false},{"k":"li","t":"يجب ألا يقل عمرك عن 18 عاما للحصول على رخصة قيادة دراجة آلية.","b":false},{"k":"li","t":"رخصة قيادة الدراجة الآلية صالحة لمدة 10 سنوات كحد أقصى.","b":false}]},{"id":"hb-speed","title":"السرعة وأضرارها","from":16,"to":23,"b":[{"k":"page","p":16},{"k":"h2","t":"2. السرعة وأضرارها"},{"k":"h3","t":"مستعملوا الطريق"},{"k":"p","t":"يشترك في استخدام الطريق مجموعة كبيرة ومختلفة من الأشخاص والمركبات تتراوح من المشاة إلى شاحنة بوزن 40 طن.","b":false},{"k":"li","t":"المشاة","b":false},{"k":"li","t":"راكبوا الدراجات الآلية والدراجات الهوائية","b":false},{"k":"li","t":"أنواع مختلفة من المركبات","b":false},{"k":"li","t":"الشاحنات الخفيفة","b":false},{"k":"li","t":"الشاحنات الكبيرة","b":false},{"k":"li","t":"الحافلات","b":false},{"k":"li","t":"مركبات اشغال عامة","b":false},{"k":"page","p":17},{"k":"p","t":"على الرغم من أن كل هذه المجموعات المختلفة تستخدم الطريق وتتفاعل فيما بينها، وكذلك تنتقل بسرعات مختلفة للغاية.","b":false},{"k":"p","t":"فمثلاا يتحرك المشاة بسرعة لا تتعدى 5-4 كم/ساعة. بينما تتحرك المركبات بسرعات أعلى بكثير من ذلك تصل إلى 100 كم/ساعة.","b":false},{"k":"p","t":"قد يؤدي هذا الاختلاف في السرعة إلى خلق حالات عالية الخطورة لكافة مستعملي الطريق. حتى الآن، نحن كمشاة اعتدنا بشكل أساسي على التحرك بسرعة السير على الأقدام، وقد تعلمنا على مر الأيام أن نتقن تلك السرعة، والبشر لم يخلقوا بشكل يمكنهم التحرك بسرعة عالية – وعلى نحو طارئ تبدأ السرعة العالية من 30-20 كم/ساعة. وهو ما يجعل الأمر غاية في الصعوبة بالنسبة للبشر تقدير سرعات أعلى بشكل صحيح، ولهذا السبب هم بحاجة إلى مساعدة تقنية من عداد السرعة.","b":false},{"k":"p","t":"تعلم السيطرة على السرعات العالية هي عملية تتطلب قدرا كبيرا من الخبرة، ولا يمكن إجراء تقييم سليم للسرعات العالية إلا من خلال التفاعل المشترك للعين والعقل. ثمة خطر آخر نواجهه هو حقيقة أننا نقوم بتحريك كتل كبيرة. فمثلا بمساعدة مركبة، يمكننا نقل كتل تزن من 1500 كغم إلى 3500 كغم بسرعات عالية جدا، ويمكن أن يكون لذلك عواقب وخيمة في حالة الاصطدام مع مركبة أو شخص.","b":false},{"k":"p","t":"السرعة؟ الوزن؟","b":false},{"k":"page","p":18},{"k":"h3","t":"المبدأ الأساسي عند قيادة المركبة:"},{"k":"li","t":"1. يجب دائما تكييف سرعة القيادة مع الظروف المحيطة.","b":false},{"k":"li","t":"2. يجب اختيار سرعة القيادة بطريقة تجعل من الممكن التوقف في الوقت المناسب لتجنب الاصطدام مع عائق أو خطر ما.","b":false},{"k":"p","t":"هل يمكنك التفكير في بعض الأمثلة؟","b":false},{"k":"p","t":"دون ادناه بعض الامثلة للتحكم بالسرعة حسب ظروف الطريق.","b":false},{"k":"page","p":19},{"k":"h3","t":"مسافة التوقف:"},{"k":"p","t":"مسافة التوقف هي المسافة التي تقطعها المركبة من لحظة إدراك السائق بوجود خطر حتى التوقف الكامل للمركبة.","b":false},{"k":"p","t":"مسافة التوقف هي مسافة ردة الفعل (الإدراك) بالإضافة إلى مسافة الفرملة.","b":false},{"k":"page","p":20},{"k":"h3","t":"مسافة ردة الفعل (الإدراك):"},{"k":"p","t":"مسافة ردة الفعل هي المسافة التي تقطعها المركبة من اللحظة التي يدرك فيها السائق وجود خطر حتى استخدام الفرامل. وبما أنه يمكن تقدير زمن ردة الفعل «القياسي» بثانية واحدة، فإن مسافة ردة الفعل هي المسافة المقطوعة في ثانية واحدة.","b":false},{"k":"p","t":"فعندما ترى عقبة أو خطرا (غير متوقع) على الطريق وتدرك أنه يتعين عليك التوقف لتجنب وقوع حادث، فسوف يستغرق ذلك الأمر بعض الوقت لإحداث ردة فعل وتحريك قدمك إلى دواسة الفرامل.","b":false},{"k":"p","t":"ستحتاج في المتوسط إلى ثانية واحدة لإحداث ردة فعل.","b":false},{"k":"p","t":"خلال هذا الوقت، تكون سيارتك متحركة دون تقليل السرعة، والمسافة التي قطعتها خلال الوقت الذي تستغرقه لإحداث ردة فعل هي مسافة ردة الفعل.","b":false},{"k":"p","t":"ما الذي يمكنك فعله لإحداث ردة فعل بشكل أسرع؟","b":false},{"k":"p","t":"متى ستحتاج إلى وقت أطول لإحداث ردة فعل؟","b":false},{"k":"h3","t":"متى تصبح مسافة ردة الفعل (الإدراك) أطول؟"},{"k":"li","t":"في حالة السرعات العالية","b":false},{"k":"li","t":"في حالة تشتت الانتباه أو التعب","b":false},{"k":"li","t":"إذا كان قائد المركبة تحت تأثير المخدرات أو تحت تأثير عقاقير مسببة للنعاس","b":false},{"k":"li","t":"إذا كان قائد المركبة تحت تأثير الكحول","b":false},{"k":"page","p":21},{"k":"h3","t":"مسافة الفرملة:"},{"k":"p","t":"مسافة الفرملة هي المسافة التي تقطعها المركبة من لحظة قيام السائق بالضغط على الفرامل حتى تتوقف المركبة توقفا تاما وكاملا. عندما تضغط على دواسة الفرامل، سوف تقطع مركبتك مسافة الفرملة قبل توقفها بشكل تام.","b":false},{"k":"p","t":"سنقوم بحساب مسافة الفرملة لعملية فرملة قوية نسبيا على طريق جاف. قد تصبح المسافة أقصر إذا قمت بالفرملة بشكل كبير قدر المستطاع (فرملة الطوارئ).","b":false},{"k":"p","t":"ستصبح المسافة أطول إذا كانت الطريق زلقة.","b":false},{"k":"h3","t":"متى تصبح مسافة الفرملة أطول؟"},{"k":"li","t":"في حالة السرعات العالية","b":false},{"k":"li","t":"عندما تكون حمولة المركبة ثقيلة","b":false},{"k":"li","t":"بسبب سوء حالة الطريق (رمل أو ثلج على الطريق، سطح مبلل، إلخ.)","b":false},{"k":"li","t":"بسبب الإطارات السيئة","b":false},{"k":"li","t":"بسبب عطل أو عدم كفائة الفرامل","b":false},{"k":"page","p":22},{"k":"h3","t":"حساب مسافات التوقف"},{"k":"p","t":"مسافة التوقف = مسافة ردة الفعل + مسافة الفرملة مسافة ردة الفعل = (السرعة/10) × 3 (افتراض: الوقت المستغرق لإحداث رد فعل = ثانية واحدة)","b":false},{"k":"p","t":"مسافة الفرملة = (السرعة/10) x (السرعة/10)","b":false},{"k":"p","t":"(افتراض: فرملة قوية على سطح جاف )","b":false},{"k":"p","t":"نظرا لحقيقة أن القيادة تتطلب اتخاذ قرارات في غضون ثوان فقط، فمن المنطقي أن نكون قادرين على تحديد عدد الأمتار التي يمكن أن تسيرها المركبة في بضع ثوان.","b":false},{"k":"p","t":"سرعة القيادةمسافة ردة الفعلمسافة الفرملةمسافة التوقف 30. كم/س9 م9 م18 م 50. كم/س15م25 م40 م 60. كم/س18 م36 م54 م 80. كم/س24م64م88 م 100كم/س30م100 م130 م 120كم/س36 م144 م180 م","b":false},{"k":"page","p":23},{"k":"h3","t":"كيف يمكنك تقليل مسافة التوقف؟"},{"k":"li","t":"تخفيف السرعة","b":false},{"k":"li","t":"زيادة الانتباه","b":false},{"k":"li","t":"كن مستعد للفرملة، وضع قدمك على دواسة الفرامل دون الضغط عليها","b":false},{"k":"remember","t":" السرعة و/أو عدم تكييف السرعة بحسب الطريق وحالة المرور هي السبب وراء العديد من حوادث السير!"}]},{"id":"hb-accidents","title":"الحوادث المرورية","from":24,"to":30,"b":[{"k":"page","p":24},{"k":"h2","t":"3. الحوادث المرورية"},{"k":"p","t":"* يتم تسجيل الحوادث إحصائيا كإصابات إذا أدى الحادث إلى الوفاة بعد مرور أكثر من شهر من تاريخ وقوع الحادث.","b":false},{"k":"p","t":"** يتم تسجيل الحوادث إحصائيا على أنها وفيات","b":false},{"k":"li","t":"إذا أسفر الحادث عن موت شخص مصاب على الفور","b":false},{"k":"li","t":"إذا أسفر الحادث إلى وفاة الشخص المصاب خلال شهر واحد من تاريخ وقوعه.","b":false},{"k":"page","p":25},{"k":"h3","t":"أسباب ارتفاع أعداد الحوادث والوفيات على الطرق في المملكة العربية"},{"k":"h3","t":"السعودية:"},{"k":"li","t":"السرعة الزائدة","b":false},{"k":"li","t":"عدم الالتزام بقوانين المرور على الطريق","b":false},{"k":"li","t":"استخدام الجوال وعدم ربط حزام الامان اثناء القيادة","b":false},{"k":"li","t":"عدم اتخاذ المسار المناسب والتغيير المفاجىء للمسار","b":false},{"k":"li","t":"حالة المركبة والطريق","b":false},{"k":"page","p":26},{"k":"h3","t":"أنواع الحوادث المرورية"},{"k":"p","t":"قد تكون الحوادث المرورية حوادث بسيطة أو كبيرة","b":false},{"k":"li","t":"حوادث المرور البسيطة حادث مروري ينجم عنه أضرار في ممتلكات خاصة أو عامة، لكن الأضرار لا تتجاوز 5 آلاف ريال سعودي حادث مروري ينجم عنه إصابة شخصية لا يلزم نقلها إلى المستشفى","b":false},{"k":"li","t":"حوادث المرور الكبيرة حوادث مرور ينجم عنها وفيات حوادث مرور ينجم عنها إصابات خطيرة: إصابات تتطلب نقل المريض إلى المستشفى وإجراء عملية له حوادث مرور ينجم عنها إصابات خطيرة: حوادث تؤدي إلى خسائر في الأموال الخاصة أو العامة","b":false},{"k":"page","p":27},{"k":"h3","t":"متى يترتب على الحادث مسؤولية قانونية؟"},{"k":"p","t":"يترتب على حادث المرور مسؤولية قانونية إذا كان نتيجة إهمال أو استهتار أو انتهاك لقوانين المرور. يتم تحديد معدل الخطأ من خلال نسبة الإهمال أو اللامبالاة أو عدم مراعاة أنظمة المرور وفقا للمعيار النسبي: (100%، 75%، 50%، 25%).","b":false},{"k":"li","t":"يعرف الإهمال على النحو التالي: الفشل في ممارسة درجة معينة من الانتباه في ظل الظروف، حيث يتطلب القانون حماية الآخرين أو مصالحهم التي قد تتأثر سلبا نتيجة لغياب مثل هذا الانتباه.","b":false},{"k":"li","t":"يعرف قلة الاحتراز أو عدم إبداء الحذر على النحو التالي: خطأ ناتج عن فعل يرتكبه السائق يشير إلى وجود تقصير أو سوء إدارة العواقب، حيث يظهر السائق إهمال متعمد أو مقصود للقانون والحياة البشرية، على سبيل المثال من خلال القيادة بسرعة كبيرة في شارع مزدحم مما يتسبب في وفاة لا سمح الهل أو اصابة أحد الماره.","b":false},{"k":"li","t":"يعرف عدم مراعاة أنظمة المرور على النحو التالي: عدم الامتثال للقوانين بشكل يؤدي لحوادث ينجم عنها إصابات أو وفيات أو اتلاف ممتلكات.","b":false},{"k":"page","p":28},{"k":"h3","t":"ينبغي على كل سائق عمل ما يلي عند وقوع حادث مروري"},{"k":"p","t":"هناك نوعين من الحوادث","b":true},{"k":"li","t":"1- حادث ينجم عنه إصابات:","b":false},{"k":"li","t":"الاتصال بالمرور (911 / 993 )","b":false},{"k":"li","t":"الاتصال بالهلال الاحمر 997","b":false},{"k":"li","t":"2- حادث ينجم عنه تلف:","b":false},{"k":"li","t":"الاتصال بنجم تحميل تطبيق نجم وتصوير الحادث من جميع الزوايا ايقاف المركبة بعيدا عن الزحام ان امكن حدد موقع الحادث وادخل البيانات و من ثم تأكيد رقم الهاتف.","b":false},{"k":"page","p":29},{"k":"h3","t":"عواقب تجاهل هذه القوانين"},{"k":"li","t":"سيؤدي عدم الامتثال لهذه القوانين إلى دفع مبلغ يصل إلى ألفي ريال سعودي و/أو السجن لمدة تصل إلى 3 أشهر","b":false},{"k":"li","t":"من يغادر مكان الحادث دون سبب سوف يعتبر هاربا من العدالة وسوف تتخذ السلطات المختصة إجراءا قانونيا بحقه.","b":false},{"k":"h3","t":"لا يجوز نقل المركبات المتورطة في حادث إلا في الحالات التالية"},{"k":"li","t":"أعاقة المركبة حركة المرور أو شكلت تهديدا للسلامة العامة","b":false},{"k":"li","t":"كان الحادث بسيطا وواضح ، واتفق الطرفان على كيفية حدوثه","b":false},{"k":"h3","t":"يجب أن يشرع طرفا الحادث على الفور بتقديم تقرير يحتوي على"},{"k":"li","t":"بيان لظروف الحادث وموقعه","b":false},{"k":"li","t":"نوع الحادث","b":false},{"k":"li","t":"نوع المركبات التي اشتركت في الحادث","b":false},{"k":"h3","t":"الحوادث التي تؤدي إلى الوفاة أو الإصابة الخطيرة"},{"k":"li","t":"اذا نتج عن الحادث إصابة او وفاة يتم إيقاف السائق مدة لا تتجاوز 72 ساعة","b":false},{"k":"li","t":"يجوز تمديد هذه الفترة من قبل المحكمة المختصة.","b":false},{"k":"li","t":"يجب الإفراج عن السائق على الفور إذا تم دفع غرامة مالية أو تقديم بوليصة التأمين المطلوبة.","b":false},{"k":"h3","t":"الحوادث التي تؤدي إلى الإصابة بشكل كلي أو جزئي بسبب تناول السائق"},{"k":"h3","t":"للكحول أو نتيجة التفحيط"},{"k":"li","t":"يتم تسليم السائق إلى المدعي العام للمحكمة المختصة لرفع دعوى قضائية ضده.","b":false},{"k":"h3","t":"قوة قاهرة"},{"k":"li","t":"يمكن التنازل عن العقوبة إذا كان الحادث قد نجم عن قوة قاهرة. وخلال التحقيق ، يجب أن يشرح السائق الذي شارك في الحادث الظروف التي أدت إلى وقوع ذلك الحادث.","b":false},{"k":"page","p":30},{"k":"p","t":"مالذي يمكن ان تفعله للحد من حوادث المرور؟","b":true},{"k":"p","t":"دون ادناه خمس تصرفات سوف تتقيد بها للحد من الحوادث المرورية 1- 2- 3- 4- 5-","b":false}]},{"id":"hb-traffic","title":"إدارة المرور: المهام والأهمية","from":31,"to":31,"b":[{"k":"page","p":31},{"k":"h2","t":"4. إدارة المرور – المهام والأهمية"},{"k":"p","t":"يمثل منسوبي المرور الدولة ويحق لهم تطبيق القانون، وبالتالي يجب اتباع تعليماتهم في كافة الحالات، ويمكن التعرف عليهم من خلال الزي أو الشارة الرسمية الخاصة بهم. تتمثل مسؤوليات منسوبي المرور في العمل على مراقبة الطرق وفحص رخص القيادة.","b":false},{"k":"h3","t":"مهام إدارة الطرق وحركة المرور:"},{"k":"li","t":"تنفيذ الضوابط المرورية","b":false},{"k":"li","t":"مقاضاة الجرائم الجنائية","b":false},{"k":"li","t":"اتخاذ إجراءات تصحيحية للمخالفات المرورية","b":false},{"k":"li","t":"ضبط السرعة وأخذ قياسات المسافة","b":false},{"k":"h3","t":"التصرف السليم في الضوابط المرورية يجب على جميع السائقين الالتزام بلوائح المرور على الطرق العامة ويجب اتباع تعليمات منسوبي"},{"k":"p","t":"المرور. يمكن لإدارة المرور أيضا إصدار أوامر تتعارض مع أنظمة المرور العادية، وبالتالي يجب الالتزام بهذه التعليمات والحرص على عدم تعرض أي شخص للخطر.","b":false},{"k":"p","t":"على سبيل المثال: الاشارة الضوئية خضراء ويأمرك رجل المرور بالتوقف او العكس","b":false}]},{"id":"hb-violations","title":"قائمة المخالفات والعقوبات ونظام النقاط","from":32,"to":44,"b":[{"k":"page","p":32},{"k":"h3","t":"قائمة المخالفات والعقوبات"},{"k":"h3","t":"جدول المخالفات (1) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية (150-100) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. قيادة المركبة في الأسواق التي لا يسمح بالقيادة فيها.","b":false},{"k":"li","t":"2. ترك المركبة مفتوحة وفي وضع التشغيل بعد مغادرتها.","b":false},{"k":"li","t":"3. عدم وجود تأمين سار للمركبة.","b":false},{"k":"li","t":"4. عبور المشاة للطرق من غير الأماكن المخصصة لهم.","b":false},{"k":"li","t":"5. عدم تقيد المشاة بالإشارات الخاصة بهم.","b":false},{"k":"li","t":"6. وقوف المركبة في أماكن غير مخصصة للوقوف.","b":false},{"k":"li","t":"7. عدم إعطاء أفضلية المرور للمشاة أثناء عبورهم في المسارات المخصصة لهم.","b":false},{"k":"page","p":33},{"k":"h3","t":"جدول المخالفات (2) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية (300-150) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. عدم استخدام إشارة الانعطاف عند الاتجاة لليمين أو اليسار أو التجاوز أو تغيير المسار.","b":false},{"k":"li","t":"2. الرجوع إلى الخلف في الطريق العام لمسافة تزيد على عشرين مترا.","b":false},{"k":"li","t":"3. قيام سائق الدراجة الآلية أو العادية- أو ما في حكهما- بالتعلق بأي مركبة أخرى ،أو سحب أو حمل أشياء تعرض مستخدم الطريق للخطر.","b":false},{"k":"li","t":"4. مخالفة قواعد استعمال أنوار التلاقي.","b":false},{"k":"li","t":"5. عدم حمل رخصة القيادة أو رخصة السير أثناء القيادة.","b":false},{"k":"li","t":"6. إساءة استعمال منبه المركبة.","b":false},{"k":"li","t":"7. عدم تقديم المركبة للفحص الفني الدوري.","b":false},{"k":"li","t":"8. مخالفة تنظيمات السير على الطريق.","b":false},{"k":"li","t":"9. عدم ربط حزام الأمان.","b":false},{"k":"li","t":"10. وضع حواجز داخل المركبة أو خارجها تعوق رؤية السائق.","b":false},{"k":"li","t":"11. عدم ترك السائق مسافة كافية بين مركبته والمركبة التي أمامه، تسمح له بتفادي وقوع حادث.","b":false},{"k":"li","t":"12. التحرك بالمركبة بسرعة عالية، بحيث تحدث الإطارات صوتا عاليا.","b":false},{"k":"li","t":"13. التجمهر في موقع الحادث.","b":false},{"k":"li","t":"14. قيام السائق بتجاوز مجموعة من المركبات أمام إشارات المرور أو نقاط الضبط الأمني باستخدام كتف الطرق او المسار المخصص للإنعطاف.","b":false},{"k":"li","t":"15. عدم توفر المتطلبات النظامية للمقطورة.","b":false},{"k":"page","p":34},{"k":"h3","t":"جدول المخالفات (3) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية (500-300) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. عدم اتخاذ الاحتياطات اللازمة عند إيقاف المركبة في حالات الطوارئ على الطرق العامة.","b":false},{"k":"li","t":"2. رمي أجسام خارج المركبة.","b":false},{"k":"li","t":"3. التباطؤ في السير على نحو يعرقل الحركة.","b":false},{"k":"li","t":"4. الانشغال بغير الطريق أثناء قيادة المركبة.","b":false},{"k":"li","t":"5. استعمال المكابح (الفرامل) بشكل مفاجئ لغير ضرورة.","b":false},{"k":"li","t":"6. عدم التقيد بتنظيمات السير عند تقاطعات الطرق.","b":false},{"k":"li","t":"7. عدم الالتزام بحدود المسارات المحددة على الطريق.","b":false},{"k":"li","t":"8. إحداث ضوضاء باستعمال أجهزة من داخل المركبة، أو ارتكاب أي سلوك يتنافى مع الآداب العامة، أثناء القيادة.","b":false},{"k":"li","t":"9. القيادة برخصة قيادة صلاحيتها منتهية.","b":false},{"k":"li","t":"10. عدم استخدام مقاعد الأمان المخصصة للأطفال.","b":false},{"k":"li","t":"11. ترك المركبة في طريق منحدرة مع عدم اتخاذ الاحتياطات اللازمة.","b":false},{"k":"li","t":"12. ترك الأطفال دون سن (العاشرة) في المركبة دون مرافق راشد.","b":false},{"k":"page","p":35},{"k":"h3","t":"جدول المخالفات (4) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية (900-500) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. ملاحقة مركبات الطوارئ أثناء استعمال المنبهات الخاصة بها.","b":false},{"k":"li","t":"2. القيادة على الطريق بمركبات مخصصة للاقتناء.","b":false},{"k":"li","t":"3. عدم الوقوف تماما عند إشارة قف.","b":false},{"k":"li","t":"4. عدم الوقوف وقوفا تاما عند إشارة (أمامك أفضلية) في حالة مرور مركبات على الطريق المعطاة له الأفضلية.","b":false},{"k":"li","t":"5. عدم إعطاء الأفضلية للمركبة القادمة من اليمين عند الوصول إلى تقاطع متساوي الأفضليات في آن واحد وعندما لا يكون هناك إشارات أولوية.","b":false},{"k":"li","t":"6. عدم إعطاء الأفضلية للمركبات التي على الطريق الرئيسية في حالة عدم وجود إشارة أفضلية.","b":false},{"k":"li","t":"7. عدم التقيد بإشارات رجل الأمن اليدوية عند تنظيمه للحركة وعدم إعطاء إشارته الأولوية على الإشارات الضوئية.","b":false},{"k":"li","t":"8. عدم إعطاء الأفضلية للمركبات التي بداخل الدوار من قبل المركبات التي خارجه في حالة عدم وجود إشارات ضوئية أو رجل مرور يوجه السير.","b":false},{"k":"li","t":"9. قيادة المركبة داخل الأنفاق من غير إضاءة أنوارها.","b":false},{"k":"li","t":"10. زيادة أبعاد الحمولة المنقولة لمركبات النقل الخفيف على الحد المسموح به.","b":false},{"k":"li","t":"11. قيام سائق مركبة الطوارئ باستعمال المنبهات الخاصة بها من غير ضرورة.","b":false},{"k":"li","t":"12. عدم إعطاء أفضلية المرور في ملتقيات الطرق أو تقاطعاتها لسائق المركبة المتقدم على غيره في حال عدم وجود لوحات تنظم ذلك.","b":false},{"k":"li","t":"13. عدم قيام السائق في حال تغيير اتجاهه بالدوران للخلف بإعطاء أفضلية المرور للمركبات القادمة من الاتجاهات الأخرى.","b":false},{"k":"li","t":"14. عدم قيام السائق في حال إغلاق جزء من الطريق بإعطاء الأفضلية لمن كان طريقه مفتوحا.","b":false},{"k":"li","t":"15. عدم قيام السائق الذي يرغب في تغيير مساره بإعطاء الأفضلية لسائق المركبة التي تسير في اتجاه مستقيم في حال سير المركبتين متحاذيتين بشكل متواز.","b":false},{"k":"li","t":"16. عدم إعطاء أفضلية المرور للمركبات القادمة من طريق رئيسي في حالة تقاطعها مع طريق فرعي أو طريق ترابي.","b":false},{"k":"li","t":"17. عدم إعطاء أفضلية المرور لوسائل النقل العام كالقطارات أو الحافلات وما في حكمها في حال سيرها على المسارات المخصصة لها.","b":false},{"k":"li","t":"18. نقل الركاب في الأماكن غير المخصصة لهم في المركبة.","b":false},{"k":"li","t":"19. استخدام السائق بيده أي جهاز محمول أثناء سير المركبة.","b":false},{"k":"page","p":36},{"k":"li","t":"20. الوقوف في أماكن وقوف ذوي الاحتياجات الخاصة من غير هذه الفئة المسموح لها.","b":false},{"k":"li","t":"21. وضع كتابة أو رسم أو ملصق أو أي بيان آخر على جسم المركبة دون موافقة الجهات المختصة.","b":false},{"k":"li","t":"22. تسيير مركبة تحدث تلويثا للبيئة على الطرق العامة.","b":false},{"k":"li","t":"23. تظليل زجاج المركبة دون التقيد بالضوابط التي تضعها الإدارة المختصة.","b":false},{"k":"li","t":"24. استعمال المركبة لغير الغرض الذي رخصت من أجله.","b":false},{"k":"li","t":"25. عدم تغطية الحمولة المنقولة وتثبيتها.","b":false},{"k":"page","p":37},{"k":"h3","t":"جدول المخالفات (5) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية (2000-1000) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. دخول الشاحنات والمعدات الثقيلة وما في حكمها إلى المدن أو الخروج منها في الأوقات غير المسموح بها.","b":false},{"k":"li","t":"2. قيادة المركبة برخصة قيادة لا تتناسب مع حجم المركبة ونوع استخدامها.","b":false},{"k":"li","t":"3. الوقوف على خطوط السكة الحديدية.","b":false},{"k":"li","t":"4. نقل عدد من الركاب يزيد على العدد المحدد في رخصة السير.","b":false},{"k":"li","t":"5. رفض إبراز الوثائق الخاصة بالسائق أو المركبة للمصرح لهم الاطلاع عليها.","b":false},{"k":"li","t":"6. قيادة المركبة بلوحات غير واضحة أو بها تلف.","b":false},{"k":"li","t":"7. سير المركبة بلا لوحة أمامية.","b":false},{"k":"li","t":"8. عدم إنهاء إجراءات تعديل مجال استعمال المركبة.","b":false},{"k":"li","t":"9. عدم إخراج المركبة المعدة للتصدير خلال المدة المحددة.","b":false},{"k":"li","t":"10. عدم ارتداء الخوذة أثناء قيادة الدراجة الآلية.","b":false},{"k":"li","t":"11. قيادة المركبة قبل الحصول على رخصة قيادة أو في حال سحب الرخصة.","b":false},{"k":"li","t":"12. ترك أجسام على الطرق العامة تعرض السلامة العامة للخطر.","b":false},{"k":"li","t":"13. عدم إعطاء أفضلية المرور لمركبات المواكب الرسمية أو الطوارئ.","b":false},{"k":"li","t":"14. القيادة على أكتاف الطريق أو على الأرصفة أو المسارات التي تمنع القيادة فيها.","b":false},{"k":"li","t":"15. النزول أو الركوب أثناء سير المركبات.","b":false},{"k":"li","t":"16. عبور المشاة للطرق السريعة.","b":false},{"k":"li","t":"17. التجاوز في المناطق التي يمنع فيها التجاوز، مثل المنعطفات والمرتفعات.","b":false},{"k":"li","t":"18. عدم وجود إنارة جانبية أو عواكس أو سواتر للشاحنات والمقطورات.","b":false},{"k":"li","t":"19. عدم استخدام الأنوار اللازمة عند السير ليلاا أو في الأحوال الجوية التي تكون فيها الرؤية غير واضحة.","b":false},{"k":"li","t":"20. عدم تثبيت اللوحة في مكانها المخصص.","b":false},{"k":"li","t":"21. التجمهر في مواقع التفحيط.","b":false},{"k":"li","t":"22. زيادة أبعاد الحمولة المنقولة لمركبات النقل الثقيل على الحد المسموح به.","b":false},{"k":"li","t":"23. إجراء أي تعديل أو إضافة على جسم المركبة أو هيكلها، يغير معالمها أو تجهيزاتها الأساسية دون اتخاذ الإجراءات النظامية.","b":false},{"k":"li","t":"24. قيادة المركبة دون توفر التجهيزات اللازمة، مثل المكابح والأنوار وما في حكمهما.","b":false},{"k":"li","t":"25. استخدام لوحات غير صادرة من الإدارة المختصة.","b":false},{"k":"page","p":38},{"k":"h3","t":"جدول المخالفات (6) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية من (6000-3000) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. تجاوز إشارة المرور الضوئية أثناء الضوء الأحمر.","b":false},{"k":"li","t":"2. تجاوز حافلات النقل المدرسي عند توقفها للتحميل أو التنزيل.","b":false},{"k":"li","t":"3. العبث بعلامات الطريق أو العاكسات أو الشاخصات المنظمة لحركة السير.","b":false},{"k":"li","t":"4. عدم الوقوف عند مراكز الضبط الأمني أو نقاط التفتيش أو عدم الوقوف للدورية الأمنية عند وجود توجيه أو علامة توجب الوقوف.","b":false},{"k":"li","t":"5. استخدام أجهزة غير مصرح بها في المركبة أو وضع شعارات أو ملصقات تتنافى مع الآداب العامة.","b":false},{"k":"li","t":"6. قيادة المركبة بالاتجاه المعاكس لحركة السير.","b":false},{"k":"li","t":"7. المراوغة بسرعة بين المركبات على الطرق العامة.","b":false},{"k":"li","t":"8. إجراء سباق للمركبات على الطرق العامة، أو السير في مواكب دون الحصول على تصريح.","b":false},{"k":"li","t":"9. عدم التزام الشاحنات والمعدات الثقيلة بالسير في المسار الأيمن في الطريق المتعدد المسارات.","b":false},{"k":"li","t":"10. عدم قيام أصحاب الحيوانات بإبعادها عن حرم الطريق المعتمد.","b":false},{"k":"li","t":"11. تركيب تجهيزات في المركبة كتلك الخاصة بالمركبات الرسمية ومركبات الطوارئ.","b":false},{"k":"li","t":"12. تسيير مركبات الأشغال العامة على الطرق قبل اتخاذ الإجراءات اللازمة لتلافي أضرارها، بما في ذلك عدم وضع الشرائح العاكسة على جانبي مؤخرة المركبة.","b":false},{"k":"li","t":"13. سير المركبة بلا لوحة خلفية، أو بلا لوحات.","b":false},{"k":"li","t":"14. طمس لوحات المركبة.","b":false},{"k":"page","p":39},{"k":"h3","t":"جدول المخالفات (7) في لائحة نظام المرور"},{"k":"h3","t":"الغرامة المالية (5000- 10000) ريال لكل من المخالفات التالية:"},{"k":"li","t":"1. قيادة المركبة تحت تأثير مسكر أو مخدر ، أو عقاقير محذر من القيادة تحت تأثيرها.","b":false},{"k":"li","t":"2. القيام بأعمال الطرق قبل التنسيق مع الإدارة المختصة.","b":false},{"k":"li","t":"3. سماح أصحاب الحيوانات بعبور حيواناتهم من غير الأماكن المخصصة لها، أو دون التنسيق مع الجهات المختصة.","b":false},{"k":"li","t":"4. استخدام لوحات غير عائدة للمركبة.","b":false},{"k":"li","t":"5. طمس رقم هيكل المركبة أو محاولة طمسه.","b":false},{"k":"page","p":40},{"k":"h3","t":"جدول المخالفات (8) في لائحة نظام المرور"},{"k":"li","t":"1. السرعة من 120 كلم- ساعة فأقل.","b":false},{"k":"p","t":"السرعة المحددة على الطريق مقدار تجاوز السرعة المحددة قيمة الغرامة بالريال من 120 كلم - ساعة فأقل.","b":false},{"k":"p","t":"(الحد الأدنى - الحد الأعلى) التجاوز بأكثر من 10كلم - ساعة إلى 20كلم - ساعة (300-150)","b":false},{"k":"p","t":"التجاوز بأكثر من 20كلم - ساعة إلى 30كلم - ساعة (300 -500)","b":false},{"k":"p","t":"التجاوز بأكثر من 30كلم - ساعة إلى 40كلم - ساعة (1000-800)","b":false},{"k":"p","t":"التجاوز بأكثر من 40كلم - ساعة إلى 50كلم - ساعة (1500-1200)","b":false},{"k":"p","t":"التجاوز بأكثر من 50 - ساعة (2000-1500)","b":false},{"k":"li","t":"2. السرعة 140كلم-ساعة السرعة المحددة على الطريق مقدار تجاوز السرعة المحددة قيمة الغرامة المالية 140 كلم - ساعة (الحد الأدنى - الحد الأعلى) التجاوز بأكثر من 5 كلم - ساعة إلى 10كلم - ساعة (500-300) التجاوز بأكثر من 10 كلم - ساعة إلى 20كلم - ساعة (1000-800)","b":false},{"k":"p","t":"التجاوز بأكثر من 20 كلم - ساعة إلى 30كلم - ساعة (1500-1200)","b":false},{"k":"p","t":"التجاوز بأكثر من 30 كلم - ساعة (2000-1500)","b":false},{"k":"p","t":"*نظام المرور الصادر بالأمر السامي الكريم رقم ( م/ 115 ) وتاريخ 05/ 12/ 1439","b":false},{"k":"page","p":41},{"k":"h3","t":"التفحيط والقيادة المتهورة هو مخالفة مرورية، يعاقب عليها بما يلي:"},{"k":"li","t":"المرة الأولى: يتم حجز المركبة لمدة 15 يوما ودفع غرامه 20 الف ريال، ويجب على السلطات النظر في سجن السائق.","b":false},{"k":"li","t":"المرة الثانية: يتم حجز المركبة لمدة شهر واحد ودفع غرامه 40 الف ريال، ويجب على السلطات النظر في سجن السائق.","b":false},{"k":"li","t":"المرة الثالثة: مصادرة المركبة ودفع غرامه 60 الف ريال .","b":false},{"k":"li","t":"لا تتم مصادرة المركبات المستأجرة أو المسروقة، لكن يجب دفع غرامة مالية بقيمة المركبة المستأجرة أو المسروقة.","b":false},{"k":"h3","t":"ارتكاب مخالفة مرورية:"},{"k":"p","t":"يجب على السائق الذي يرتكب مخالفة مرورية أن يبقى داخل المركبة لحين وصول شرطي المرور واقترابه من السائق واستكمال إجراءات تسجيل المخالفة. يتم كتابة المخالفة المرورية بثلاث نسخ، حيث يتم تسليم إحدى النسخ إلى السائق المخالف بينما يتم إرسال الإثنتين الأخرتين إلى السلطات المختصة لتسجيل المخالفة.","b":false},{"k":"p","t":"هذا لا يشمل المخالفات المسجلة تلقائي . يجب ملء حقول ورقة المخالفة ويجب على السائق المخالف توقيعها. إذا رفض السائق المخالف توقيعها أو لم يكن موجودا، فيجب كتابة ذلك في المخالفة. إذا لم يكن السائق متاحا أو غادر مكان الحادث، فيجب توثيق لوحة أرقام المركبة وإضافة كافة التفاصيل في ورقة المخالفة بأكبر قدر ممكن. تتم معاقبة السائق المخالف عن كل مخالفة منفصلة، حتى وإن كانت مدرجة في ورقة واحدة. بالإمكان تسديد المخالفات عن طريق الهاتف المصرفي أو آلات الصرف الآلي، وكذلك بالإمكان الاستعلام عن المخالفات عن طريق موقع أبشر الإلكتروني.","b":false},{"k":"h3","t":"نموذج المخالفة"},{"k":"p","t":"يجب معالجة مخالفات المرور في نموذج موحد خاص بالمخالفات. تعالج الإدارة العامة للمرور سجل المخالفات برقم تسلسلي ويحتوي على ما يلي:","b":false},{"k":"p","t":"المعلومات ذات الصلة ب","b":false},{"k":"li","t":"السائق","b":false},{"k":"li","t":"المركبة","b":false},{"k":"li","t":"فئة المخالفة","b":false},{"k":"li","t":"تاريخ ووقت ومكان المخالفة","b":false},{"k":"li","t":"الفترة المعطاة لدفع الغرامة المالية","b":false},{"k":"page","p":42},{"k":"h3","t":"دفع الغرامة"},{"k":"p","t":"يجوز للسائق المخالف دفع الحد الأدنى من الغرامة في أقرب مركز مختص خلال مدة أقصاها ثلاثين يوما من تاريخ المخالفة، وسيحصل على إيصال رسمي عند سداده لتلك الغرامة. في حالة عدم دفع الغرامة خلال المدة المحددة، تلزم السلطة المختصة السائق المخالف بدفع الحد الأقصى من الغرامة المفروضة عليه. يجب أن تنص القواعد التنفيذية على إجراءات تسجيل المخالفات والمدة المحددة لدفع الغرامات المالية.","b":false},{"k":"h3","t":"النقاط المسجلة"},{"k":"li","t":"يتم تخصيص عدد محدد من النقاط لكل مخالفة.","b":false},{"k":"li","t":"يعتمد عدد النقاط على درجة الخطر على السلامة العامة.","b":false},{"k":"li","t":"يتم تسجيل النقاط في سجل السائق المخالف.","b":false},{"k":"li","t":"سيتم سحب رخصة القيادة إذا بلغ عدد النقاط 24.","b":false},{"k":"li","t":"علما أن الحد الأقصى للنقاط هو 24 نقطة.","b":false},{"k":"page","p":43},{"k":"p","t":"نظام نقاط المخالفات المرورية","b":false},{"k":"p","t":"المخالفة ا ل نقاط","b":true},{"k":"li","t":"1. القيادة تحت تأثير مسكر أو مخدر 24","b":true},{"k":"li","t":"2. التفحيط24","b":true},{"k":"li","t":"3. عدم التوقف عند الإشارة الحمراء12","b":true},{"k":"li","t":"4. القيادة في الاتجاه المعاكس للسير12","b":true},{"k":"li","t":"5. القيادة السريعة والمتهورة بين المركبات على الطرق العامة8","b":true},{"k":"li","t":"6. عدم الامتثال لإشارات وتعليمات رجل المرور 8","b":true},{"k":"li","t":"7. قيادة مركبات بدون فرامل أو أضواء8","b":true},{"k":"li","t":"8. عدم التوقف التام عند إشارة قف 6","b":true},{"k":"li","t":"9. عدم احترام قواعد حق الأولوية6","b":true},{"k":"p","t":"10. تجاوز حد السرعة القصوى بأكثر من 25 كم / ساعة6","b":true},{"k":"p","t":"11. عدم إعطاء الأولوية للمركباة في الدوار6","b":true},{"k":"p","t":"12. تجاوز المركبات الأخرى في أماكن يمنع عندها التجاوز6","b":true},{"k":"p","t":"13. التوقف على السكك الحديدية6","b":true},{"k":"p","t":"14. تجاوز السرعة القصوى بما لا يزيد عن 25 كم / ساعة4","b":true},{"k":"p","t":"15. القيادة في مسارات غير مصممة لذلك4 تجاوز الحالافت المدرسیة عندما تتوقف للسماح للطلاب بالدخول إليها أو الخروج 4 منها","b":true},{"k":"p","t":"17. عدم تغطية أو ربط الأحمال المنقولة4","b":true},{"k":"p","t":"18. إجراء تعديلات إضافية على جسم المركبة دون اتباع الإجراءات القانونية4","b":true},{"k":"p","t":"19. عدم ربط أحزمة الأمان2","b":true},{"k":"p","t":"20. استخدام الهاتف المحمول باليد 2","b":true},{"k":"p","t":"21. عدم ارتداء خوذة عند قيادة دراجة نارية2","b":true},{"k":"page","p":44},{"k":"h3","t":"سحب رخصة القيادة"},{"k":"h3","t":"يتم تطبيق إجراء سحب الرخصة إذا بلغت نسبة المخالفات المسجلة في سجل"},{"k":"h3","t":"السائق المخالف 24 نقطة."},{"k":"p","t":"للمرة الأولى في السنة الهجرية الواحدة: يتم سحب رخصة القيادة لمدة 3 أشهر للمرة الثانية في السنة الهجرية الواحدة: يتم سحب رخصة القيادة لمدة 6 أشهر للمرة الثالثة في السنة الهجرية الواحدة: يتم سحب رخصة القيادة لسنة هجرية واحدة للمرة الرابعة في السنة الهجرية الواحدة: يتم سحب رخصة القيادة بشكل دائم","b":false},{"k":"h3","t":"السحب الدائم للرخصة"},{"k":"p","t":"إذا تم القبض على سائق تم سحب رخصته أثناء قيادة مركبة خلال فترة سحب الرخصة، فسيتم التعامل معه على أنه ليس حاملا لرخصة قيادة ويجب إحالته إلى المحكمة المختصة لمضاعفة العقوبة. ويمكن توجيه السائق لحضور برنامج إعادة التأهيل لمدة 15 يوما في إحدى مدارس تعليم القيادة. إذا تم سحب رخصة القيادة بشكل دائم، يمكن التقدم للحصول على رخصة جديدة بعد مرور عام من تاريخ سحب الرخصة، شريطة أن يكون السائق قد أتم برنامج إعادة التأهيل لشهر واحد في مدرسة لتعليم القيادة والنجاح في الاختبار النظري والعملي. في حالة سحب الرخصة بشكل مؤقت أو دائم، ينطبق ما سبق على جميع فئات رخص القيادة.","b":false}]},{"id":"hb-roadparts","title":"أجزاء الطريق","from":45,"to":50,"b":[{"k":"page","p":45},{"k":"h2","t":"5. أجزاء الطريق"},{"k":"h3","t":"الطريق"},{"k":"h3","t":"الطريق مخصص لحركة المركبات"},{"k":"li","t":"يمكن أن يحتوي الطريق على عدة مسارات، ويمكن تحديد معالم تلك المسارات على سطح الطريق","b":false},{"k":"li","t":"الطريق الرئيسي هو طريق يتم الوصول إليه والخروج منه من خلال المداخل والمخارج ولا يخدم العقارات بشكل مباشر.","b":false},{"k":"li","t":"طريق الخدمة يخدم الملكيات المجاورة بشكل مباشر.","b":false},{"k":"page","p":46},{"k":"h3","t":"منطقة سكنية وبلدة مفتوحة"},{"k":"p","t":"هي منطقة جغرافية تتواجد ضمن المدينة مخصصة الموجودة داخل شبكة الطرق . البلدة المفتوحة هي شبكة الطرق خارج المدن والبلدات","b":false},{"k":"h3","t":"جزيرة مرورية"},{"k":"p","t":"الجزيرة المرورية هي منطقة صغيرة ومرتفعة وتعمل على تقسيم الحركة بإتجاهين مختلفين .","b":false},{"k":"h3","t":"مسار الدمج"},{"k":"p","t":"هو عبارة عن مسار تغيير يسمح بدمج حركة المرور في الطريق العادي أو الطريق السريع.","b":false},{"k":"page","p":47},{"k":"h3","t":"التقاطعات"},{"k":"p","t":"يشير هذا المصطلح إلى أي تقاطع أو عبور أو تفرع للطرق على مستوى واحد أو عدة مستويات، بما في ذلك المساحة التي يتم تشكيلها كنتيجة لذلك.","b":false},{"k":"p","t":"أنواع التقاطعات محكومة و غير محكومة","b":true},{"k":"p","t":"التقاطعات المحكومة:","b":true},{"k":"li","t":"تنظمها إشارات ضوئية","b":false},{"k":"li","t":"تنظمها إشارات طريق","b":false},{"k":"li","t":"ينظمها رجل المرور","b":false},{"k":"p","t":"التقاطعات الغير محكومة:","b":true},{"k":"li","t":"بدون أي علامات ويحكمها قانون الأولوية","b":false},{"k":"page","p":48},{"k":"p","t":"مسار الدراجة الهوائية يتم تمييز مسار الدراجة الهوائية من خلال إشارة مرور إلزامية ومخصصة لراكبي الدراجات الهوائية","b":true},{"k":"p","t":"مسار الخيل يتم تمييز مسار ركوب الخيل من خلال إشارة مرور إلزامية ومخصصة لراكبي الخيول","b":true},{"k":"p","t":"مسار الرصيف / المشاة يعد مسار الرصيف أو المشاة جزءا من الطريق وهو مخصص لاستخدام المشاة وليس للمركبات","b":true},{"k":"p","t":"مسار عبور المشاة","b":true},{"k":"li","t":"يعتبر مسار عبور المشاة جزءا محددا من الطريق حيث يحق للمشاة عبوره","b":false},{"k":"li","t":"يمكن تمييز مسارات عبور المشاة بعلامات بيضاء ترسم على الطريق.","b":false},{"k":"li","t":"يتم الإعلان عن مسارات عبور المشاة بواسطة إشارات المرور.","b":false},{"k":"remember","t":" يرجى التأكد من عدم الخلط بين هاتين الإشارتين."},{"k":"p","t":"العلامة الزرقاء الدائرية التي بداخلها خطوط بيضاء هي إشارة إلزامية تشير إلى الرصيف أو مسار المشاة العلامة المثلثية ذات الإطار الأحمر والخطوط السوداء هي إشارة تحذير تشير إلى معبر أطفال","b":false},{"k":"page","p":49},{"k":"h3","t":"التصرف السليم في ممرات المشاة"},{"k":"h3","t":"في ممرات المشاة التي تخلو من إشارات المرور أو ينظمها رجل المرور عند الاقتراب من ممرات المشاة، يجب على السائقين أن يبطئوا السرعة التي تجعل التوقف أمام"},{"k":"p","t":"معبر المشاة ممكنا في حال أراد المشاة العبور. يجب عدم تعريض سلامة المارة أثناء عبورهم للخطر","b":false},{"k":"page","p":50},{"k":"h3","t":"في ممرات المشاة التي تحتوي على إشارة عبور المشاة"},{"k":"p","t":"ضوء أخضر متواصل يسمح للمشاة بعبور الطريق ولكنهم بحاجة إلى مراقبة حركة المرور.","b":true},{"k":"p","t":"ضوء أخضر ذات وميض متقطع يشير الضوء الأخضر المتقطع إلى أن إشارة عبور المشاة ستصبح حمراء قريب ، وبالتالي على المشاة الذين يعبرون الطريق الإسراع في عبوره، والمشاة الذين يقتربون من الممر يجب أن ينتظروا وألا يدخلوا الممر.","b":true},{"k":"p","t":"ضوء أحمر أو برتقالي لا يسمح للمشاة بعبور الطريق ممرات المشاة خارج مناطق التقاطع التي يمكن الإشارة إليها بواسطة أضواء صفراء ذات وميض في هذه الحالة، يكون للمشاة أولوية العبور، لكنهم بحاجة إلى مراقبة حركة المرور بعناية وحذر، خاصة في المناطق التي يسمح للسائقين بقيادة المركبات بسرعة.","b":true},{"k":"remember","t":" هل تعلم أن السيارة تزن 25 ضعف وزن أحد المشاة؟ لذا احرص دوما على توخي الحذر ومراقبة حركة المرور!"}]},{"id":"hb-guidance","title":"عناصر توجيه حركة المرور","from":51,"to":51,"b":[{"k":"page","p":51},{"k":"h2","t":"6. عناصر توجيه حركة المرور"},{"k":"h3","t":"تخدم عناصر توجيه حركة المرور غرض تأمين حركة المرور وتوجيهها وإدارتها."},{"k":"h3","t":"أنواع عناصر توجيه حركة المرور"},{"k":"li","t":"علامات الطريق","b":false},{"k":"li","t":"الأعمدة","b":false},{"k":"li","t":"الإشارات الضوئية","b":false},{"k":"li","t":"إشارات المرور","b":false},{"k":"h3","t":"يمنع بشكل عام:"},{"k":"li","t":"إتلاف أو تغيير عناصر توجيه حركة المرور","b":false},{"k":"li","t":"إزالة أو تغيير مواقعها","b":false},{"k":"li","t":"وضع ملصقات أو إعلانات على أعمدة أو أضواء أو إشارات الطرق أو غيرها من أدوات توجيه حركة المرور","b":false},{"k":"h3","t":"أبرز علامات الطريق:"},{"k":"li","t":"خطوط متصلة / متصلة مزدوجة – يحظر عبور الخطوط متصلة","b":false},{"k":"li","t":"خطوط متقطعة – يجوز تجاوز هذه الخطوط","b":false},{"k":"li","t":"ممرات المشاة","b":false},{"k":"li","t":"أسهم تشير للاتجاهات","b":false}]},{"id":"hb-signs","title":"إشارات المرور","from":52,"to":73,"b":[{"k":"page","p":52},{"k":"h2","t":"7. إشارات المرور"},{"k":"h3","t":"أنواع إشارات المرور"},{"k":"h3","t":"إشارات التحذير جميع إشارات التحذير هي مثلثة الشكل وذات إطار أحمر"},{"k":"page","p":53},{"k":"h3","t":"إشارات تنظيمية علامات التوجيه هي دائرية الشكل. إذا كانت بيضاء بإطار أحمر فأنها تدل على المنع."},{"k":"p","t":"إذا كانت زرقاء، فهي إلزامية إشارات حق الأولوية إشارات حق الأولوية علامات حق الأولوية لها شكل خاص. عادة ما تكون مثمنة أو على شكل مثلث مقلوب","b":false},{"k":"page","p":54},{"k":"h3","t":"إشارات إرشادية علامات الاستعلام تأتي مستطيلة أو مربعة الشكل وبألوان مختلفة."},{"k":"h3","t":"إشارات مناطق العمل المؤقتة إشارات مناطق العمل المؤقتة تأتي صفراء اللون بإطار أحمر. وعادة ما تستخدم للإشارة إلى إجراء أعمال على الطرق أو طرق بديلة."},{"k":"p","t":"يتم وضع علامات المرور بشكل رئيسي على الجانب الأيمن من الطريق وتكون عاكسة بشكل يضمن رؤيتها بشكل جيد أثناء الليل وكذلك أثناء النهار، ويجب على جميع مستعملي الطرق احترامها والإلتزام بها.","b":false},{"k":"page","p":55},{"k":"h3","t":"7،1 إشارات التحذير :"},{"k":"h3","t":"الشكل واللون: بشكل عام كافة إشارات التحذير تكون على شكل مثلث رأسه في الأعلى."},{"k":"p","t":"وتأتي بخلفية بيضاء ورموز سوداء وإطار أحمر.","b":false},{"k":"h3","t":"الغرض منها: تستخدم إشارات التحذير لتنبيه وتحذير السائقين وجميع مستعملي الطرق الآخرين من الخطر أو المواقف الخطرة الموجودة أو المحتملة على الطريق أو الشارع أو المناطق المجاورة لها. يجب وضع إشارات التحذير بعيدا بما يكفي أمام الخطر بحيث يتمكن السائق من الاستجابة لها في الوقت المناسب وألا يتفاجأ بوجود ذلك الخطر بشكل يؤثر سلبا على سلوكه وردة فعله. وتوجه إشارات التحذير السائق إلى توخي الحذر وتنبيهه لتكييف سرعته حسب الخطر المشار إليه لضمان سلامته"},{"k":"p","t":"وسلامة الركاب وكذلك سلامة جميع مستعملي الطريق الآخرين.","b":false},{"k":"h3","t":"أمثلة على علامات التحذير إذا تم الإشارة إلى ضيق الطريق من خلال رمز عنق الزجاجة (الاختناقات)، يجب على السائق تقليل السرعة لأنه قد يكون من الضروري التوقف عند تلك الإشارة"},{"k":"p","t":"في حال كانت هناك مركبات قادمة. إذا تمت الإشارة إلى مستوى منخفض، يجب على السائق تقليل السرعة وربما السير بغيار منخفض للاستفادة من قدرة المحرك على الكبح.","b":false},{"k":"page","p":56},{"k":"h3","t":"7،2 إشارات تنظيمية"},{"k":"h3","t":"الشكل واللون: بشكل عام، تكون علامة التوجيه دائرية الشكل مع خلفية بيضاء ورموز سوداء وإطار أحمر، مع"},{"k":"p","t":"بعض الاستثناءات مثل:","b":false},{"k":"h3","t":"الغرض منها: تستخدم إشارات التوجيه لتنبيه السائقين ومستعملي الطرق حول مجموعة من القواعد التوجيهية"},{"k":"p","t":"الخاصة بحركة المرور وحدود السرعة والمحظورات والالتزامات (مثل اتجاه القيادة المحدد). يجب الالتزام بهذه القيود والمحظورات والالتزامات عند القيادة أو استخدام الطريق، وتجسد هذه الإشارات القوانين والقواعد المرورية، وكل من يخالفها يخضع لدفع غرامة مالية والعقوبة. هناك عدة أنواع وفئات من إشارات التوجيه.","b":false},{"k":"h3","t":"تصنيف الإشارات التوجيهية أو التنظيمية:"},{"k":"p","t":"تأتي إشارات حق الأولوية بأشكال وأنواع مختلفة","b":false},{"k":"li","t":"إشارة «قف» إشارة «قف» مثمنة الشكل (تحتوي على ثمانية زوايا). وهذا يجعل من السهل التعرف عليها ورؤيتها من الأمام والخلف","b":false},{"k":"li","t":"إشارة «أعط حق الأولوية» إشارة «إعط حق الأولوية» مثلثة الشكل برأس معكوس للأسفل وهذا يجعل من السهل التعرف عليها ورؤيتها من الأمام والخلف.","b":false},{"k":"page","p":57},{"k":"h3","t":"إشارات تشير إلى اتجاهات القيادة المنظمة"},{"k":"p","t":"إشارات تشير إلى بداية ونهاية الحد الأدنى للسرعة اشارات بداية ونهاية الحد الادنى للسرعةاشارات اتجاهات القيادة","b":false},{"k":"h3","t":"إشارات المنع"},{"k":"li","t":"عادة ما تأتي بخلفية بيضاء مع أطار أحمر وأحرف ورموز أو أرقام سوداء اللون.","b":false},{"k":"li","t":"تشير إلى قيود مثل حدود السرعة","b":false},{"k":"li","t":"تشير أيضا إلى حالات المنع مثل ممنوع الدخول.","b":false},{"k":"li","t":"علامات حظر القيادة هي دائرية الشكل وتشير إلى محظورات محددة للقيادة، على سبيل المثال قيادة الشاحنات.","b":false},{"k":"li","t":"تشير إشارات الانتظار إلى المناطق التي يسمح فيها أو يحظر فيها الانتظار أو إيقاف المركبة.","b":false},{"k":"p","t":"علامة ممنوع الوقوف والانتظار علامة ممنوع الوقوف علامة ممنوع الدخول علامة حد السرعة ومسموح الانتظار","b":false},{"k":"page","p":58},{"k":"h3","t":"7،3 إشارات إرشادية"},{"k":"h3","t":"الشكل واللون: بشكل عام تكون إشارات الاستعلام مستطيلة أو مربعة الشكل وتأتي بأحجام وألوان مختلفة وتحتوي رموز مختلفة، ويعتمد حجمها على طول الرسالة المراد إيصالها، ويتم تحديد لون الإشارة"},{"k":"p","t":"وفقا لنوع الرسالة المراد إيصالها كما هو موضح أدناه.","b":false},{"k":"h3","t":"الغرض منها: تشير إشارات الإرشادية إلى الظروف المهمة المتعلقة بحركة المرور وتوفر لمستعملي الطرق معلومات وتفاصيل مفيدة فيما يتعلق باستخدام الطريق، وهي تستخدم في المقام الأول لتوجيه السائقين ومستعملي الطريق على طول الطريق إلى المدن والقرى والشوارع والوجهات الأخرى. كما تشير أيضا إلى التقاطعات والمسافات والاتجاهات وخدمات المرافق، فضالاعن الأماكن الدينية والأماكن الجغرافية أو الجيولوجية أو التاريخية الهامة. بشكل عام، توفر هذه الإشارات المعلومات للسائقين وتساعدهم على سلوك أقصر الطرق للوصول إلى وجهتهم. هناك عدة أنواع وفئات من"},{"k":"p","t":"إشارات إرشادية .","b":false},{"k":"h3","t":"تصنيف إشارات إرشادية"},{"k":"p","t":"خلفية زرقاء بحروف بيضاء","b":false},{"k":"li","t":"عادة ما توجد خارج حدود المدينة أو الاحياء السكنية","b":false},{"k":"li","t":"تشير إلى المدن والقرى","b":false},{"k":"page","p":59},{"k":"p","t":"خلفية خضراء بحروف بيضاء","b":false},{"k":"li","t":"عادة ما توجد داخل حدود المدينة في المناطق السكنية","b":false},{"k":"li","t":"تشير إلى الشوارع والأحياء داخل المدن خلفية بيضاء بحروف سوداء","b":false},{"k":"li","t":"تؤدي إلى المرافق الهامة مثل المطارات أو مراكز المدينة خلفية بنية بحروف بيضاء","b":false},{"k":"li","t":"تشير إلى المزارع والمجمعات الترفيهية والمتاحف.","b":false},{"k":"li","t":"كما تشير أيضا إلى الأماكن الدينية.","b":false},{"k":"page","p":60},{"k":"h3","t":"7،4 اشارات مناطق العمل المؤقتة"},{"k":"h3","t":"الشكل واللون: أشكال إشارات مناطق العمل المؤقتة هي نفس أشكال الفئات الثلاثة الرئيسية التي تنقسم إليها"},{"k":"p","t":"إشارات المرور (دائرة، مثلث، مربع ومستطيل) مع إختلاف اللون بحيث يكون لونها اصفر بإطار أحمر.","b":false},{"k":"h3","t":"الغرض منها: إن الغرض من إشارات مناطق العمل المؤقتة هو نفس الغرض من التي تستخدم فيه الإشارات"},{"k":"p","t":"السابق ذكرها التحذيرية والتنظيمية و الإرشادية مع اختلاف بسيط وهو انها مؤقتة على الطريق.","b":false},{"k":"page","p":61},{"k":"h3","t":"7،5 إشارات المرور حسب نوعها"},{"k":"h3","t":"إشارات التحذير"},{"k":"p","t":"تقاطعات انعطافات","b":false},{"k":"page","p":62},{"k":"h3","t":"إشارات التحذير"},{"k":"p","t":"اختناقات مطبات إشارات ضوئية","b":false},{"k":"page","p":63},{"k":"h3","t":"إشارات التحذير"},{"k":"p","t":"منحدرات ومرتفعات حالات وظروف الطريق حيث يجب توخي أقصى حالات الحذر","b":false},{"k":"page","p":64},{"k":"h3","t":"إشارات التحذير"},{"k":"p","t":"معبر مشاة معبر حيوانات إشارات تحذير إضافية","b":false},{"k":"page","p":65},{"k":"h3","t":"إشارات تنظيمية (مانعه) والإشارات الإلزامية"},{"k":"p","t":"إشارات تنظيمية (مانعه) إشارات تمنع الدخول للجميع ولنوع معين من مستعملي الطرق","b":false},{"k":"page","p":66},{"k":"h3","t":"إشارات تنظيمية (مانعه)"},{"k":"p","t":"حدود على الشاحنات حدود السرعة حدود التجاوز","b":false},{"k":"page","p":67},{"k":"h3","t":"إشارات تنظيمية (مانعه)"},{"k":"p","t":"نهاية كل الحدود أو البعض منها الانتظار ووقوف السيارات إشارات منع إضافية","b":false},{"k":"page","p":68},{"k":"h3","t":"إشارات تنظيمية (إلزامية)"},{"k":"p","t":"الحد الأدنى للسرعة إشارات تشير إلى اتجاهات الحركة","b":false},{"k":"page","p":69},{"k":"h3","t":"إشارات إرشادية"},{"k":"p","t":"إشارات خارج حدود المدينة","b":false},{"k":"page","p":70},{"k":"h3","t":"إشارات إرشادية"},{"k":"p","t":"علامات توجيه إلى المدن والقرى علامات توجيه إلى الشوارع والأحياء داخل المدن علامات توجيه إلى المرافق الهامة علامات توجيه إلى المزارع والمجمعات الترفيهية والمتاحف","b":false},{"k":"page","p":71},{"k":"h3","t":"إشارات مناطق العمل المؤقتة"},{"k":"page","p":72},{"k":"h3","t":"إشارات مناطق العمل المؤقتة"},{"k":"page","p":73},{"k":"h3","t":"تذكر جيدا"},{"k":"p","t":"لا يكفي مجرد الشعور بالأمان، بل يجب عليك البقاء في حالة تأهب ولعب دور نشط في جعل الطرق في المملكة آمنة.","b":false}]},{"id":"hb-u2","title":"الوحدة الثانية: السلوك","from":74,"to":75,"b":[{"k":"page","p":74},{"k":"h2","t":"الوحدة الثانية"},{"k":"h2","t":"السلوك"},{"k":"page","p":75}]},{"id":"hb-coop","title":"السلوك التعاوني","from":76,"to":82,"b":[{"k":"page","p":76},{"k":"h2","t":"1. السلوك التعاوني"},{"k":"h3","t":"قواعد السلوك الصحيحة لمستعملي الطريق:"},{"k":"li","t":"القيادة بأمان يجوز قيادة المركبة فقط إذا كان السائق في حالة بدنية وعقلية جيدة وقادر على قيادة المركبة بأمان دون تعريض الآخرين للخطر بالإضافة لحمل رخصة قيادة سارية المفعول","b":false},{"k":"li","t":"القيادة باحترام يجب على كافة مستعملي الطريق الانتباه لمستعملي الطريق الآخرين واحترام حقوق جميع مستعملي الطريق الآخرين","b":false},{"k":"li","t":"القيادة بحذر يجب على كافة السائقين القيادة بحذر شديد على الطرق العامة","b":false},{"k":"li","t":"القيادة بشكل قانوني يجب اتباع القوانين والقواعد وإشارات المرور.","b":false},{"k":"li","t":"الامتثال لأوامر إدارة المرور احرص دائما على اتباع التعليمات المقدمة من إدارة المرور، حتى إذا كانت تتعارض مع التعليمات الأخرى، إلا إذا كان يمكن أن تعرض سلامة السائق أو مستعملي الطريق للخطر.","b":false},{"k":"remember","t":" ما هي الأشياء التي يمكن أن تفعلها لتكون سائق متعاون؟"},{"k":"page","p":77},{"k":"remember","t":" بشكل عام، يجب على جميع السائقين الالتزام بجميع أنظمة المرور في جميع الأوقات. بالإضافة إلى ذلك، يجب على السائقين أيضا الالتزام بأوامر إدارة المرور، حتى إذا كانت هذه التعليمات تتعارض مع القوانين الأخرى. وبالإضافة إلى ذلك من المهم أن يستخدم السائقون الحكم الصائب وأن يحرصوا على عدم تعريض سلامتهم أو سلامة مستعملي الطريق الآخرين للخطر."},{"k":"page","p":78},{"k":"h3","t":"أمثلة على مستعملي الطريق الآخرين"},{"k":"li","t":"مشاة","b":false},{"k":"li","t":"حيوانات","b":false},{"k":"li","t":"أنواع مختلفة من المركبات","b":false},{"k":"page","p":79},{"k":"h3","t":"مستعملو الطريق الآخرين وسلوكهم"},{"k":"h3","t":"المشاة"},{"k":"p","t":"كيف يجب على المشاة التصرف؟","b":true},{"k":"li","t":"أثناء المشي على الطريق:","b":false},{"k":"p","t":"استخدم الرصيف امشي في الاتجاه المعاكس لحركة المرور، إذا لم تعيق حركة المرور أو تعرض سلامتك للخطر","b":false},{"k":"li","t":"عند عبور الطريق: راقب إشارات ضوء المشاة أو إشارات رجل المرور تأكد دائما من عدم عرقلة حركة المرور قم بتقييم سرعة المركبات القادمة امشي بسرعة دون توقف ولا تطل المشي دون داع","b":false},{"k":"h3","t":"التصرف الصحيح عند معابر المشاة"},{"k":"p","t":"في ممرات المشاة التي تحتوي ضوء المشاة","b":true},{"k":"li","t":"الضوء الأخضر المتواصل – يسمح للمشاة بعبور الطريق ولكن يجب عليهم كذلك الانتباه لحركة المرور","b":false},{"k":"li","t":"يشير الضوء الأخضر المتقطع بأن ضوء المشاة سوف يتحول إلى اللون الأحمر، وبالتالي على من دخل الشارع إخلاؤه على الفور والتحرك بسرعة. ويجب على المشاة الذين يقتربون من معبر المشاة عدم الاقتراب منه.","b":false},{"k":"li","t":"الضوء الأحمر – لا يسمح للمشاة بعبور الطريق","b":false},{"k":"p","t":"عند خطوط المشاة التي تخلو من ضوء المشاة","b":true},{"k":"li","t":"أحيانا يتم الإشارة إلى معابر المشاة بخطوط بيضاء متجاورة، في هذه الحالة يكون للمشاة حق الأولوية ولكنهم بحاجة إلى مراقبة حركة المرور بحذر، خاصة في المناطق التي يسمح للسائقين بقيادة مركباتهم بسرعة.","b":false},{"k":"page","p":80},{"k":"h3","t":"إشارات المرور أمام خطوط المشاة وعليها"},{"k":"p","t":"على اليمين يمكنك رؤية إشارة تحذير، ويجب أن توضع في مكان بعيد عن عبور المشاة مقارنة بإشارة الاستعلام التي تراها على اليسار.","b":false},{"k":"page","p":81},{"k":"h3","t":"السلوك الصحيح للسائق عند التعامل مع المشاة"},{"k":"p","t":"السلوك الصحيح للسائق","b":true},{"k":"li","t":"عندما يكون هناك مشاة على الطريق","b":false},{"k":"li","t":"عند الاقتراب من خطوط المشاة","b":false},{"k":"p","t":"كيف يجب على السائق التصرف؟ لا تعرض سلامة المشاة على الأرصفة أو على جانب الطريق للخطر!","b":true},{"k":"li","t":"عند الاقتراب من خطوط المشاة: - تحقق من جانبي الطريق للتأكد من خلوها من المارة – أنظر حولك لرؤية الأشخاص الذين يقتربون من خطوط المشاة - قلل من السرعة وكن مستعدا للتوقف","b":false},{"k":"li","t":"عند خطوط المشاة: - لا تعرقل حركة المشاة الذين بدؤوا بالفعل عبور الشارع - إذا قمت بالانعطاف عند التقاطع، يجب عليك الانتباه للمشاة عند مفترق الطرق – وإذا لزم الأمر توقف حتى يعبروا الطريق","b":false},{"k":"page","p":82},{"k":"h3","t":"مجموعات موجهة من الناس والحيوانات"},{"k":"p","t":"يجب على من يصطحب مجموعة من الأشخاص أو قطيع من الحيوانات ارتداء أحزمة أو سترات عاكسة عند المرور على الطرق العامة.","b":false},{"k":"p","t":"قطعان الحيوانات","b":true},{"k":"li","t":"يجب حراسة القطعان","b":false},{"k":"li","t":"يجب تقسيم القطعان الكبيرة إلى مجموعات صغيرة لتسهيل عبور الطريق","b":false},{"k":"li","t":"يجب مراقبة قطعان الحيوانات الموجودة بالقرب من الطريق","b":false},{"k":"li","t":"يجب ربط قطعان الحيوانات الموجودة بعيدا عن الطريق بشكل آمن وبعيدا عن الطريق","b":false}]},{"id":"hb-priorityusers","title":"مستعملو الطريق من لهم حق الأولوية","from":83,"to":86,"b":[{"k":"page","p":83},{"k":"h2","t":"2. مستعملو الطريق من لهم حق الأولوية"},{"k":"p","t":"مركبات الطوارئ مثل الأمن العام والاسعاف","b":false},{"k":"page","p":84},{"k":"h3","t":"مركبات الطوارئ:"},{"k":"p","t":"في حركة المرور على الطرق، فإن مركبات الطوارئ على مسارات الطوارئ لها الأولوية القصوى. في حالات الطوارئ، لا يلزم سائقو مركبات الطوارئ بأي أنظمة أو محظورات، ولكن يجب ألا يعرضوا سلامتهم وسلامة الآخرين للخطر.","b":false},{"k":"p","t":"كيفية التعرف على مركبات الطوارئ","b":true},{"k":"li","t":"إشارات إنذار بصرية (مصابيح حمراء وزرقاء)","b":false},{"k":"li","t":"إشارات تحذير صوتية","b":false},{"k":"p","t":"كيفية التعامل مع مركبات الطوارئ:","b":true},{"k":"li","t":"في حالة رؤية مرکبات الطوارئ، یجب إخلاء المسار علی الفور.","b":false},{"k":"li","t":"يحظر القيادة مباشرة خلف مركبات الطوارئ ويجب ترك مسافة لا تقل عن 50 متر.","b":false},{"k":"li","t":"يجب على السائقين البقاء على الجانب الأيمن من الطريق عند اقتراب مركبة الطوارئ","b":false},{"k":"li","t":"يجب عدم الخروج من مواقف السيارات قبل أن تمر مركبة الطوارئ.","b":false},{"k":"li","t":"يجب إخلاء التقاطعات سريعا لتجنب إعاقة مركبات الطوارئ التي تقترب من تلك التقاطعات","b":false},{"k":"page","p":85},{"k":"h3","t":"حافلات المدرسة"},{"k":"p","t":"يجب أن تحمل الحافلات المدرسية العلامات والإشارات التي تشير إلى أنها مخصصة لأغراض النقل المدرسي.","b":false},{"k":"p","t":"دخول الحافلات المدرسية والخروج منها:","b":true},{"k":"li","t":"یجب أن تتوقف الحالافت المدرسیة في محطات محددة لتمكين الطلاب من الصعود إليها والخروج منها","b":false},{"k":"li","t":"يجب عدم فتح الأبواب إلى حين توقف الحافلة بشكل تام","b":false},{"k":"li","t":"يجب أن يتم الدخول إليها من الجانب الأيمن (من الرصيف)","b":false},{"k":"li","t":"على سائق الحافلة المدرسية القيادة فقط بعد التأكد من الحفاظ على سلامة الطلاب","b":false},{"k":"p","t":"كيفية التعامل مع الحافلات المدرسية:","b":true},{"k":"li","t":"إذا توقفت الحالافت المدرسية لتحميل أو إنزال اللاتميذ، يجب أن يتوقف سائقو المركبات الأخرى، ويحظر عليهم تجاوز حافلات النقل المدرسية عند توقفها لتحميل أو إنزال الطلاب.","b":false},{"k":"page","p":86},{"k":"h3","t":"المواكب الرسمية من مستعملي الطرق"},{"k":"p","t":"كيفية التعامل مع مستعملي الطريق من المواكب الرسمية على مستخدمي الطريق إفساح المرور للمواكب الرسمية بمجرد الإعلان عن اقترابها بواسطة أجهزة التنبيه الصوتية والضوئية، على أن يقفوا على الجانب الأيمن من الطريق في حال وجود تعليمات من الإدارة المختصة بذلك و ألا يغادروا إلا بعد مرورها أو وفقا للتعليمات الصادرة لهم.","b":true},{"k":"p","t":"كيفية التعامل مع مستعملي الطريق من المواكب الرسمية يجب عدم قطع المواكب الرسمية من مستعملي الطريق أو إعاقة حركتهم من قبل مستعملي الطريق الآخرين.","b":true}]},{"id":"hb-assess","title":"تقييم مستعملي الطريق","from":87,"to":88,"b":[{"k":"page","p":87},{"k":"h2","t":"3. تقييم مستعملي الطريق"},{"k":"p","t":"أثناء حركة المرور على الطرق، من الضروري تقييم مستعملي الطريق الآخرين بسرعة وأمان.","b":false},{"k":"p","t":"لتقييم سريع وصحيح لمستعملي الطريق الآخرين، ينبغي أخذ العوامل التالية بعين الاعتبار:","b":true},{"k":"li","t":"العمر يجب إعطاء انتباه خاص للأطفال أو كبار السن!","b":false},{"k":"li","t":"الانتباه هل ينتبه الأشخاص لحركة المرور؟ أم هل هم مشتتون؟ من المهم إدراك النوايا المحتملة لمستعملي الطريق الآخرين في وقت قصير لتجنب الحوادث","b":false},{"k":"p","t":"تذكري جيدا إذا لم تكن متأكدا حيال موقف ما، فحاول دائما التواصل بصريا مع الآخرين!","b":true},{"k":"page","p":88},{"k":"h3","t":"إشكالية مستعملي الطريق"},{"k":"h3","t":"الأطفال"},{"k":"p","t":"خصائص الأطفال:","b":true},{"k":"li","t":"عدم إعطاء اهتمام أو انتباه لحركة المرور","b":false},{"k":"li","t":"سهولة التشتت","b":false},{"k":"li","t":"التصرف بشكل تلقائي في أغلب الأحيان","b":false},{"k":"li","t":"عدم معرفة قواعد المرور و / أو عدم الامتثال لها","b":false},{"k":"li","t":"عدم تقييم المخاطر بشكل صحيح","b":false},{"k":"li","t":"صغر السن – لا يمكنهم استيعاب الحالات المرورية","b":false},{"k":"h3","t":"كبار السن وذوي الاحتياجات الخاصة"},{"k":"p","t":"خصائص كبار السن:","b":true},{"k":"li","t":"ارتباك وحساسية عالية","b":false},{"k":"li","t":"محدودية الحركة في أغلب الأحيان","b":false},{"k":"li","t":"مشاكل في السمع و/أو مشاكل في الرؤية أو غيرها من المشاكل","b":false}]},{"id":"hb-duties","title":"التزامات السائق","from":89,"to":96,"b":[{"k":"page","p":89},{"k":"h2","t":"4. التزامات السائق"},{"k":"h3","t":"القدرة على القيادة يجب أن يكون لائقا بدنيا وذهنيا لقيادة المركبة!"},{"k":"p","t":"يجب عليك عدم قيادة المركبة ... عندما تكون مصابا ولا تستطيع استخدام ذراعيك أو ساقيك بشكل سليم ... عندما تكون مريض ... عندما تكون منهكا ومتعبا للغاية ... عندما تكون مشتت الانتباه (على سبيل المثال استخدام الهاتف الجوال)","b":true},{"k":"p","t":"... عندما تكون في حالة انفعال يحظر عليك قيادة مركبة تحت تأثير الكحول أو المخدرات أو الدواء. (إذا كنت تتناول الدواء، فمن المهم أن تقرأ النشرة الخاصة به بعناية!)","b":false},{"k":"p","t":"الآثار المترتبة على ذلك أي سائق يقود مركبة تحت تأثير الكحول والمخدرات و / أو الدواء سوف يتم تسجيل 24 نقطة بحقه لمخالفته القواعد المرورية.","b":true},{"k":"page","p":90},{"k":"p","t":"تذكر تجنب الملهيات- مثل الالتهاء بتشغيل الأجهزة داخل المركبة واستعمال الهاتف الجوال والأكل والشرب- أثناء القيادة للحفاظ على سلامتك على الطريق وسلامة الآخرين.","b":false},{"k":"page","p":91},{"k":"h3","t":"إلتزامات ومحظورات التعامل مع المركبات"},{"k":"p","t":"إلتزامات السائق قبل القيادة","b":true},{"k":"li","t":"يجب على السائق التأكد من توفر كافة المعدات الضرورية","b":false},{"k":"li","t":"يجب على السائق التأكد من أن المركبة في حالة جيدة وآمنة للقيادة على الطريق بحيث لا تعمل على إعاقة مستعملي الطريق الآخرين أو تعريضهم للخطر","b":false},{"k":"li","t":"يجب على السائق القيام بما يلي: تنظيف النوافذ والأضواء والمرايا التأكد من عدم وجود أضرار في النوافذ والأضواء والمرايا والإطارات التأكد من حالة الأضواء وعناصر التحكم والفرامل","b":false},{"k":"page","p":92},{"k":"remember","t":" تذكر أن تتأكد من ضبط وضعية الجلوس الخاصة بك بشكل صحيح. وكذلك ضبط المرايا وربط الحزام للسائق والركاب."},{"k":"page","p":93},{"k":"h3","t":"إلتزامات السائق أثناء القيادة"},{"k":"p","t":"اتبع القواعد المرورية قم بالقيادة على المنطقة الممهدة من الطريق والبقاء في المسار المناسب وعند الحد الأقصى المحدد للسرعة. دع السائقين الآخرين يعرفون ما تنوي القيام به. على سبيل المثال لا تنس أن تعطي إشارة في حال أردت التوجه إلى اليمين أو اليسار.","b":true},{"k":"page","p":94},{"k":"h3","t":"المحظورات"},{"k":"li","t":"إشارات التحذير البصرية أو الصوتية استخدم إشارات الإنذار أو التحذير في حالات الطوارئ فقط لا تزعج المارة أو الجو العام لا تستخدم إشارات تحذير ذات نغمات أو أصوات متعددة","b":false},{"k":"li","t":"لا تطفئ المحرك أثناء القيادة","b":false},{"k":"li","t":"لا تسبب ضوضاء باستخدام المركبة","b":false},{"k":"li","t":"لا تقم بإرفاق الأغطية أو الستائر للمركبة","b":false},{"k":"li","t":"لا تضع نقوشا ورسومات وإعلانات على المركبة","b":false},{"k":"li","t":"يجب ألا يعيق السائق حركة المركبات الأخرى أو مستعملي الطريق الآخرين.","b":false},{"k":"li","t":"يحظر ترك المركبة تتدحرج إلى منحدر خلال إيقاف تشغيل المحرك","b":false},{"k":"page","p":95},{"k":"h3","t":"المحظورات"},{"k":"li","t":"لا تنقل أشخاص خارج المساحة المخصصة للركاب","b":false},{"k":"li","t":"لا تغسل أو تصلح المركبة على الطرق العامة","b":false},{"k":"li","t":"لا تبصق أو تلق القمامة أثناء القيادة","b":false},{"k":"li","t":"لا تستخدم المركبة في المواكب أو المسيرات دون إذن","b":false},{"k":"li","t":"يجب عدم قيادة المركبات في المواكب أو المسيرات (ما لم تسمح بذلك السلطات).","b":false},{"k":"li","t":"في حالة حدوث أي عطل قد يؤثر على حركة المرور أثناء القيادة، يجب إخلاء الطريق على الفور ويتعين على السائق القيادة في شارع جانبي حيث لا يتم إعاقة حركة المرور.","b":false},{"k":"remember","t":" أثناء القيادة - إذا تعطلت مركبتك، عليك إزالتها من الطريق وتأمينها إذا كان ذلك ممكنا. خلال النهار: ضع علامة تحذير واضحة في مسافة التوقف. خلال الليل: بالإضافة إلى ذلك، قم بتأمين المركبة بأضواء حمراء."},{"k":"page","p":96},{"k":"h3","t":"إلتزامات السائق بعد إيقاف المركبة:"},{"k":"li","t":"عند مغادرة المركبة، يجب على السائق ضمان ما يلي:","b":false},{"k":"p","t":"إيقاف تشغيل المركبة إزالة المفاتيح إغلاق المركبة","b":false},{"k":"li","t":"يجب على السائق وركاب المركبة التأكد من عدم تعرض أي شخص للخطر عند فتح أبواب المركبة.","b":false},{"k":"li","t":"يجب الوقوف على جانب الرصيف","b":false},{"k":"remember","t":" يمنع ترك المركبة غير مقفلة أو عدم إيقاف المحرك أو ترك المفتاح داخلها."}]},{"id":"hb-passengers","title":"نقل الركاب","from":97,"to":99,"b":[{"k":"page","p":97},{"k":"h2","t":"5. نقل الركاب"},{"k":"h3","t":"بشكل عام:"},{"k":"p","t":"نقل الركاب: ... مسموح به فقط في المركبات المخصصة لنقل الركاب ... يمنع نقل الركاب بواسطة شاحنة أو آلات ثقيلة ... يمنع نقل الركاب في صندوق المركبة الخلفي أو أي جزء خارجي من المركبة","b":true},{"k":"page","p":98},{"k":"p","t":"استخدام حزام الأمان يجب على السائق وجميع الركاب الآخرين استخدام حزام الأمان أثناء القيادة في الطرق.","b":true},{"k":"p","t":"يجب على السائق تنبيه الركاب لوضع حزام الأمان.","b":false},{"k":"p","t":"استثناءات من قانون حزام الأمان:","b":true},{"k":"li","t":"الاشخاص اللذين لا يستطيعون وضع حزام الأمان لأسباب صحية (مطلوب دليل طبي وإذن من السلطات الرسمية)","b":false},{"k":"li","t":"الاشخاص اللذين لايستطيعون وضع حزام الامان بسبب احجامهم","b":false},{"k":"p","t":"نقل الأطفال يجب وضع مسند داعم للأطفال الذين تقل اعمارهم عن 12 عاما كي يكون حزام الأمان تحت الكتف . يجب عدم وضع الأطفال الذين تقل أعمارهم عن 10 سنوات في المقعد الأمامي","b":true},{"k":"p","t":"استثناء: إذا لم تتوفر مقاعد خلفية، فيمكن وضع الطفل في المقدمة (باستخدام مقعد مناسب للأطفال).","b":true},{"k":"remember","t":" يرجى التأكد من أن كل راكب يرتدي حزام الأمان - وأن كل طفل يجلس في مقعد أمان خاص به."},{"k":"p","t":"دخول وخروج الأشخاص","b":true},{"k":"page","p":99},{"k":"p","t":"في حالة الوقوف في طريق عام او على الطريق يجب الخروج والدخول من الجانب الأيمن، ويتعين على الركاب الدخول والخروج من المركبة من منطقة الرصيف.","b":false}]},{"id":"hb-u3","title":"الوحدة الثالثة: حركة المرور","from":100,"to":101,"b":[{"k":"page","p":100},{"k":"h2","t":"الوحدة الثالثة"},{"k":"h2","t":"حركة المرور"},{"k":"page","p":101}]},{"id":"hb-general","title":"نظام القيادة العام","from":102,"to":108,"b":[{"k":"page","p":102},{"k":"h2","t":"1. نظام القيادة العام"},{"k":"h3","t":"بشكل عام"},{"k":"li","t":"يجب قيادة المركبات دائما على الجزء المعبد من الطريق","b":false},{"k":"li","t":"يجب على السائق الالتزام بجميع إشارات المرور العادية ما لم يتم إرشادهم من قبل رجل المرور","b":false},{"k":"li","t":"يجب ألا يتجاوز السائق حد السرعة المحدد","b":false},{"k":"li","t":"يجب أن يسمح السائق للمركبات الأخرى بالتجاوز عنه بأمان","b":false},{"k":"page","p":103},{"k":"h3","t":"قاعدة المسار الأيمن"},{"k":"p","t":"مسارين مع خط متقطع إذا تم تقسيم الطرق المعبدة إلى مسارين متعاكسين من خلال خط متقطع، فيجب على السائق القيادة على المسار الأيمن وألا يقطع هذا الخط إلى المسار الآخر إلا في حال أراد تجاوز مركبة أخرى أمامه.","b":false},{"k":"page","p":104},{"k":"h3","t":"قاعدة المسار الأيمن"},{"k":"p","t":"مسارين بخط مزدوج متواصل إذا تم تقسيم الطرق المعبدة إلى مسارين متعاكسين من خلال خط مزدوج متواصل، يحظر على السائقين عبور هذا الخط إلى المسار الآخر.","b":false},{"k":"page","p":105},{"k":"h3","t":"القيادة جنبا إلى جنب"},{"k":"p","t":"إذا كان الطريق مقسما إلى عدة مسارات، يمكن عندئذ للمركبات السير جنبا إلى جنب في اتجاه مواز على تلك المسارات. لكن على المركبات البطيئة استخدام المسار على أقصى اليمين ما لم تكن تتأهب للانعطاف يسارا أو إلى الاتجاه المعاكس على شكل الدوران للخلف. قبل تغيير المسار، يجب على السائق التأكد من أن هذا لن يعرض الآخرين للخطر، ويجب عليه إظهار نيته بوضوح وتحذير الآخرين.","b":false},{"k":"page","p":106},{"k":"remember","t":" هذا مثال جيد على مدى كفاءة حركة المرور عندما يلتزم غالبية السائقين بعلامات الطريق بشكل صحيح."},{"k":"page","p":107},{"k":"h3","t":"القيادة على أقصى الجانب الأيمن من الطريق"},{"k":"p","t":"يجب أن يبقى السائق في أقصى الجانب الأيمن من الطريق:","b":false},{"k":"li","t":"إذا إراد الانعطاف إلى اليمين","b":false},{"k":"li","t":"إذا كانت المركبات الأخرى على وشك التجاوز عنه","b":false},{"k":"li","t":"إذا كانت سرعة مركبته أقل من الحد الأقصى للسرعة","b":false},{"k":"li","t":"في حال كانت الرؤية ضعيفة","b":false},{"k":"li","t":"في حال كانت هناك مركبات قادمة من الاتجاه المعاكس","b":false},{"k":"page","p":108},{"k":"h3","t":"القيادة على الجانب الأيسر من الطرق"},{"k":"p","t":"يسمح بالقيادة على الجانب الأيسر من الطريق فقط إذا","b":false},{"k":"li","t":"كان من الضروري منع وقوع الحوادث وعدم إعاقة مستعملي الطريق الآخرين أو تعريضهم للخطر","b":false},{"k":"li","t":"إراد السائق تجاوز المركبات الأخرى (فقط في حال كان التجاوز مسموحا به ويمكن القيام به دون إعاقة مستعملي الطريق الآخرين أو تعريضهم للخطر)","b":false},{"k":"li","t":"تم إغلاق جزء من الجانب الأيمن (على سبيل المثال من قبل موقع بناء)، وكانت هناك إشارة بالمرور من قبل إدارة المرور أو قوات الأمن الأخرى أو عمال الطريق.","b":false},{"k":"h3","t":"التصرف عند الطرق الضيقة"},{"k":"p","t":"عند الاقتراب من الاختناقات، يجب على سائقي المركبات البقاء أقصى الجانب الأيمن من الطريق للحفاظ على مسافة جانبية كافية لمرور المركبات القادمة من الاتجاه الآخر، وإذا لزم الأمر يجب أن يوقفوا مركباتهم حتى تمر المركبات الأخرى القادمة من الاتجاه المعاكس وعدم استخدام منبه الصوت إلا للضرورة القصوى.","b":false}]},{"id":"hb-lanechange","title":"تغيير المسارات","from":109,"to":113,"b":[{"k":"page","p":109},{"k":"h2","t":"2. تغيير المسارات"},{"k":"p","t":"من الضروري تغيير المسارات في الحالات التالية:","b":true},{"k":"li","t":"تجنب عقبة","b":false},{"k":"li","t":"اختيار المسار الصحيح قبل الانعطاف","b":false},{"k":"li","t":"التجاوز عن المركبات الأخرى","b":false},{"k":"li","t":"في حال أراد السائق التوقف على الجانب الأيسر من الطريق (فقط إذا سمح له بذلك)","b":false},{"k":"p","t":"قبل تغيير المسار","b":true},{"k":"li","t":"يجب على السائق التأكد من أن هذه المناورة لن تعرضه أو تعرض الآخرين للخطر","b":false},{"k":"li","t":"يجب على السائق إظهار نيته بوضوح وتنبيه الآخرين","b":false},{"k":"p","t":"السلوك العام عند تغيير المسار","b":true},{"k":"li","t":"تأكد من أنه غير ممنوع من قبل إشارات المرور","b":false},{"k":"li","t":"يجب أن تكون قادرا على تغيير المسار دون تعريض نفسك أو مستعملي الطريق الآخرين للخطر","b":false},{"k":"li","t":"يجب الإشارة إلى قرارك بتغيير المسار قبل أن تقوم فعليا بذلك","b":false},{"k":"page","p":110},{"k":"h3","t":"النقطة العمياء"},{"k":"remember","t":" إذا كنت تعتمد فقط على المرايا الجانبية، فلن يمر وقت قبل أن تصطدم بمركبة في منطقة النقطة العمياء! لأنك تستطيع أن ترى تلك المركبات فقط إذا ألقيت نظرة على كتفك."},{"k":"page","p":111},{"k":"h3","t":"تغيير المسارات: (إلى اليسار أو إلى اليمين)"},{"k":"p","t":"قبل تغيير المسار، يجب على السائق التأكد من عدم تعرض مستعملي الطريق الآخرين لأي إعاقة أو تعريضهم للخطر. ولهذا السبب يجب عليك دائما التحقق من المرايا الخاصة بك أولاا ثم إعطاء إشارة (غماز) والتحقق من النقطة العمياء بالنظر من فوق كتف السائق والسرعة قبل إجراء هذه الخطوة.","b":false},{"k":"p","t":"المرايا الإشارة","b":true},{"k":"p","t":"الكتف السرعة تغيير المسار","b":true},{"k":"remember","t":" تذكر دائم : كلما زادت سرعة القيادة، كلما كان عليك توجيه المركبة بسلالة أكثر"},{"k":"page","p":112},{"k":"h3","t":"تغيير المسار إلى اليسار"},{"k":"p","t":"تحقق من حركة المرور في الجهة المقابلة","b":false},{"k":"p","t":"المرايا الإشارة","b":true},{"k":"p","t":"الكتف السرعة","b":true},{"k":"p","t":"التحرك تغيير المسار بحركات توجيه سلسة المرآة الداخلية المرآة الخارجية اليسرى الإشارة لليسار الكتف الأيسر تعديل السرعة التحرك: التوجيه بسلاسة","b":true},{"k":"page","p":113},{"k":"h3","t":"تغيير المسار إلى اليمين"},{"k":"p","t":"تحقق من حركة المرور في الجهة المقابلة","b":false},{"k":"p","t":"المرايا الإشارة","b":true},{"k":"p","t":"الكتف السرعة","b":true},{"k":"p","t":"التحرك تغيير المسار بحركات توجيه سلسة المرآة الداخلية المرآة الخارجية اليمنى الإشارة لليمين الكتف الأيمن تعديل السرعة التحرك: التوجيه بسلاسة","b":true}]},{"id":"hb-lanechoice","title":"اختيار المسار الصحيح للانتقال إليه","from":114,"to":122,"b":[{"k":"page","p":114},{"k":"h2","t":"3. اختيار المسار الصحيح للانتقال إليه"},{"k":"p","t":"يجب مراعاة ما يلي قبل الانتقال إلى المسار الصحيح لتغيير الطريق:","b":true},{"k":"li","t":"تأكد من أن الانعطاف لا تحظره إشارات المرور أو إشارات أخرى التي تمنع الانعطاف","b":false},{"k":"li","t":"يجب الإشارة إلى تغيير المسار أو الإنعطاف في الوقت المناسب عن طريق إشارات الإنعطاف","b":false},{"k":"li","t":"يجب ألا يتعرض مستعملو الطريق الآخرون للخطر","b":false},{"k":"li","t":"عليك الإلتزام بعلامات الطريق التي تشير إلى اتجاهات القيادة","b":false},{"k":"remember","t":" اختيار مكان وضع مركبتك يمكن أن يكون تحديا حقيقيا! لهذا من المهم التخطيط مسبقا لاختيار المسار الصحيح."},{"k":"page","p":115},{"k":"h3","t":"اختيار المسار الصحيح / الموضع الصحيح على الطريق"},{"k":"p","t":"في حال عدم وجود علامات على الطريق (عدم وجود أسهم تشير إلى الاتجاهات):","b":true},{"k":"p","t":"للانعطاف نحو اليمين:","b":true},{"k":"li","t":"يجب على السائق الانعطاف نحو اليمين من أقصى الجانب الأيمن للطريق","b":false},{"k":"p","t":"للانعطاف نحو اليسار:","b":true},{"k":"li","t":"في الطرق ذات الاتجاهين يجب أن ينتقل السائق إلى منتصف الطريق. إذا كان هناك خط فاصل، يجب أن يبقى السائق على يمين الخط الفاصل.","b":false},{"k":"li","t":"في الطرق ذات الاتجاه الواحد، يجب على السائق الانعطاف نحو اليسار من الجانب الأيسر للطريق","b":false},{"k":"p","t":"للاستدارة (على شكل حذوة فرس):","b":true},{"k":"li","t":"في الطرق ذات الاتجاهين، يجب أن ينتقل السائق إلى منتصف الطريق. إذا كان هناك خط فاصل، يجب أن يبقى السائق على يمين الخط الفاصل","b":false},{"k":"li","t":"في الطرق ذات الاتجاه الواحد أو التي توجد فيها جزيرة في المنتصف، يجب على السائق الدوران للخلف من الجانب الأيسر من الطريق (إلى يمين الجزيرة).","b":false},{"k":"page","p":116},{"k":"h3","t":"في حال وجود علامات على الطرق (وجود أسهم تشير إلى الاتجاهات):"},{"k":"p","t":"للانعطاف نحو اليمين: يجب على السائق الانعطاف نحو اليمين من المسار الذي يوجد فيه سهم يشير إلى اليمين","b":true},{"k":"p","t":"للانعطاف نحو اليسار: يجب على السائق الانعطاف نحو اليسار من المسار الذي يوجد فيه سهم يشير إلى اليسار","b":true},{"k":"p","t":"الدوران للخلف (على شكل حذوة فرس): يجب على السائق الدوران للخلف من المسار الذي يوجد فيه سهم يشير الى الدوران للخلف","b":true},{"k":"page","p":117},{"k":"h3","t":"التخطيط مسبقا"},{"k":"p","t":"لنفترض أنك تقترب من تقاطع مكون من مسارات متعددة لكل اتجاه قيادة وتريد الانعطاف نحو اليسار.","b":false},{"k":"remember","t":" في هذه الحالة تحتاج إلى التخطيط مسبق ، حيث سيعتمد المسار الصحيح على مسارك بعد الانعطاف نحو اليسار!"},{"k":"page","p":118},{"k":"h3","t":"التخطيط مسبقا – مثال 1"},{"k":"p","t":"إذا كنت ترغب في الانعطاف نحو اليسار هنا ومن ثم نحو اليمين عند التقاطع التالي ...","b":false},{"k":"p","t":"خطوة 1 ... عليك أن تسلك المسار الأول من المسارات الثلاثة المتاحة لإمكانية الإنعطاف نحو اليسار ...","b":true},{"k":"p","t":"خطوة 2 ... ثم تابع السير في هذا المسار.","b":true},{"k":"p","t":"خط وة 1 خطوة 2","b":false},{"k":"page","p":119},{"k":"h3","t":"التخطيط مسبقا – مثال 2"},{"k":"p","t":"إذا كنت ترغب في الانعطاف نحو اليسار هنا ومن ثم السير بخط مستقيم عند التقاطع التالي ...","b":false},{"k":"p","t":"خطوة 1 ... عليك أن تسلك المسار الثاني من المسارات الثلاثة المتاحة لإمكانية الإنعطاف نحو اليسار ...","b":true},{"k":"p","t":"خطوة 2 ... ثم تابع السير في هذا المسار.","b":true},{"k":"p","t":"خطوة 1 خطوة 2","b":false},{"k":"page","p":120},{"k":"h3","t":"التخطيط مسبقا – مثال 3"},{"k":"p","t":"إذا كنت ترغب في الانعطاف نحو اليسار هنا ومن ثم الانعطاف نحو اليسار عند التقاطع التالي ...","b":false},{"k":"p","t":"خطوة 1 ... عليك أن تسلك المسار الثالث من المسارات الثلاثة المتاحة لإمكانية الإنعطاف نحو اليسار ...","b":true},{"k":"p","t":"خطوة 2 ... ثم تابع السير في هذا المسار.","b":true},{"k":"p","t":"خ طوة 1 خطوة 2","b":false},{"k":"page","p":121},{"k":"h3","t":"التخطيط مسبقا عند الدوار"},{"k":"p","t":"الاقتراب من عند الدوارمغادرة الدوار الدوار الانعطاف لليمين مسار 1مسار 1مسار 1 (مخرج 1)","b":false},{"k":"p","t":"القيادة بشكل مسار 2 ( إن وجد) مسار 2 ( إن وجد) مسار 2 ( إن وجد) مستقيم (مخرج 2)","b":false},{"k":"p","t":"الانعطاف لليسار مسار 3 ( إن وجد) مسار 3 ( إن وجد) مسار 3 ( إن وجد)","b":false},{"k":"p","t":"(مخرج 3)","b":false},{"k":"p","t":"الاستدارة (مخرج 4)مسار 3 ( إن وجد) مسار 3 ( إن وجد) مسار 3 ( إن وجد)","b":false},{"k":"page","p":122},{"k":"h3","t":"إعطاء إشارة عند الدوار"},{"k":"p","t":"الاقتراب من الدوارعند الدوار الانعطاف لليمين إعطاء إشارة لليمين مواصلة إعطاء إشارة (مخرج 1)","b":false},{"k":"p","t":"لليمين القيادة بشكل بدون إشارة مستقيم (مخرج 2)عند جزيرة المخرج 1 إعطاء إشارة لليمين الانعطاف لليسار إعطاء إشارة لليسار إعطاء إشارة لليمين عند جزيرة المخرج 2 (مخرج 3)","b":false},{"k":"p","t":"الاستدارة (مخرج 4)إعطاء إشارة لليسار عند جزيرة المخرج 3 إعطاء إشارة لليمين","b":false},{"k":"remember","t":" في حال التزم كافة السائقين بهذه القواعد، فإن حركة المرور ستكون سلسة حول الدوار دونما أي مشاكل تذكر."}]},{"id":"hb-turning","title":"الانعطاف والرجوع إلى الخلف","from":123,"to":125,"b":[{"k":"page","p":123},{"k":"h2","t":"4. الانعطاف والرجوع إلى الخلف"},{"k":"h3","t":"الانعطاف"},{"k":"li","t":"يجب الإشارة إلى كل إنعطاف في وقت مبكر بما فيه الكفاية من خلال إشارة الانعطاف","b":false},{"k":"li","t":"یجب أن يقوم السائق بإبطاء سرعة المركبة في وقت مبكر وأن لا يقوم بالضغط على الفرامل بصورة مفاجئة ما لم يكن من الضروري لأغراض اللاسمة","b":false},{"k":"li","t":"يجب أن يكون السائق حذرا وأن يترك مساحة كافية بينه وبين المركبة الموجودة أمامه.","b":false},{"k":"h3","t":"الانعطاف نحو اليمين يجب أن يتم الانعطاف نحو اليمين من خلال منحنى ضيق والبقاء على أقصى الجانب الأيمن من"},{"k":"p","t":"الطريق","b":false},{"k":"page","p":124},{"k":"h3","t":"الانعطاف نحو اليسار"},{"k":"p","t":"يجب أن يتم الانعطاف نحو اليسار من خلال منحنى عريض والاتجاه إلى الجانب الأيمن من الطريق الأخر","b":false},{"k":"page","p":125},{"k":"h3","t":"الرجوع إلى الخلف"},{"k":"li","t":"يجب الإشارة إلى ذلك بوضوح","b":false},{"k":"li","t":"لا يجوز القيادة إلى الخلف على الطرق العامة إلا في حالة الضرورة ولمسافة قصيرة لا تتجاوز 20 متر كحد أقصى (يمنع القيادة إلى الخلف على الطرق السريعة)","b":false},{"k":"li","t":"قبل الرجوع إلى الخلف، يجب على السائق التأكد من خلو الطريق من المركبات وأن الرجوع إلى الخلف لن يعرض سلامة مستعملي الطريق الآخرين للخطر.","b":false}]},{"id":"hb-u4","title":"الوحدة الرابعة: المعابر","from":126,"to":128,"b":[{"k":"page","p":126},{"k":"h2","t":"الوحدة الرابعة"},{"k":"h2","t":"المعابر"},{"k":"page","p":127},{"k":"page","p":128},{"k":"h2","t":"المعابر"},{"k":"p","t":"المعابر هي أماكن تتقاطع فيها طرق أخرى أو خطوط سكك حديدية أو غيرها من مستعملي الطريق. لذلك يمكن لمستعملي الطريق الآخرين العبور من اليسار أو من اليمين مما قد يؤدي إلى مواقف خطرة. لتجنب الحوادث، يتم تمييز تلك المعابر وتأمينها بشكل خاص.","b":false},{"k":"remember","t":" يمكن تنظيم التقاطعات من خلال الإشارات الضوئية أو إشارات رجل المرور. إذا لم يكن الأمر كذلك، يجب على السائقين احترام قواعد حق الأولوية."}]},{"id":"hb-lights","title":"التقاطعات التي تنظمها الإشارات الضوئية","from":129,"to":133,"b":[{"k":"page","p":129},{"k":"h2","t":"1. تقاطعات الطرق"},{"k":"p","t":"يمكن تنظيم مختلف تقاطعات الطرق من خلال الإشارات الضوئية أو إشارات شرطة المرور. في حال لم يتم التحكم في التقاطع من خلال الإشارات الضوئية أو إشارات رجل المرور، يجب على السائقين احترام قواعد حق الأولوية.","b":false},{"k":"h3","t":"1،1 التقاطعات التي تنظمها الإشارات الضوئية"},{"k":"p","t":"الإشارات الضوئية يتم الإعلان عن الإشارات الضوئية من خلال علامات تحذير","b":true},{"k":"page","p":130},{"k":"h3","t":"تسلسل ومعنى الإشارات الضوئية"},{"k":"li","t":"الضوء الأحمر - توقف عند ظهور الضوء الأحمر، يجب أن تتوقف المركبات عند خط التوقف أو يجب ألا تتجاوز مستوى عمود الإشارة الضوئية. إذا لم يكن هناك خط توقف، يجب أن يتوقف السائق في مكان يمكنه فيه رؤية الإشارات الضوئية.","b":true},{"k":"p","t":"يجب على السائق عدم تجاوز منطقة عبور المشاة بعد التوقف عند الضوء الأحمر، يمكن للسائق الانعطاف نحو اليمين ما لم يحظر ذلك بواسطة إحدى إشارات المرور. في أي حال، يجب على السائق التأكد من أنه من الممكن الانعطاف بأمان.","b":false},{"k":"li","t":"الضوء الأخضر-إذن بالقيادة عندما تتحول إشارة الضوء إلى اللون الأخضر، يجب أن يبدأ السائق بالقيادة في وقت معقول. إذا تباطأت حركة المرور أو توقفت ولم يتمكن السائق من عبور التقاطع، فلايجب عليه الدخول إلى منطقة التقاطع على الرغم من حق الأولوية أو الضوء الأخضر.","b":true},{"k":"li","t":"الضوء الأصفر / البرتقالي - انتباه / توقف إذا كان من الممكن التوقف دون تعريض المرء نفسه للخطر أو غيره من مستعملي الطريق، يجب أن يتوقف سائق المركبة ويجب أن لا يتجاوز خط التوقف.","b":true},{"k":"page","p":131},{"k":"h3","t":"تسلسل ومعنى الإشارات الضوئية ذات الضوء المتقطع"},{"k":"li","t":"الضوء الأحمر المتقطع: له نفس معنى إشارة قف. يجب أن يتوقف السائق عند خط التوقف أو على مستوى عمود الإشارة الضوئية. إذا تم تركيب ضوء أحمر متقطع عند نقطة عبور المشاة أو عند ملتقى سكة حديد، يجب على السائق عدم عبور خط المشاة أو السكك الحديدية ويجب ألا يتحرك قبل إخلاء الطريق من المشاة أو عربات السكك الحديدية","b":true},{"k":"remember","t":" على الرغم من أن الضوء الأحمر الوامض له نفس معنى علامة قف ، إلا أنه من الأفضل دائما ملاحظة محيطك والتأكد من أنه من الآمن التوقف قبل القيام بذلك عند الاقتراب من الضوء الأحمر الوامض."},{"k":"li","t":"الضوء الأصفر / البرتقالي المتقطع:","b":true},{"k":"p","t":"له نفس معنى إشارة حق الأولوية يسمح للسائق مواصلة القيادة بحرص شديد وحذر","b":false},{"k":"page","p":132},{"k":"remember","t":" حتى إذا كان مسموحا الانعطاف إلى اليمين، تأكد من التوقف دائما والانتباه بعناية أثناء عبور الأشخاص والمركبات!"},{"k":"p","t":"الانعطاف نحو اليمين عند وجود ضوء أحمر","b":true},{"k":"li","t":"قم بقيادة مركبتك في أقصى الجانب الأيمن من الطريق وابق هناك قدر الإمكان","b":false},{"k":"li","t":"قم بإعطاء إشارة نحو اليمين أثناء انعطافك نحو اليمين عند وجود الضوء الأحمر","b":false},{"k":"li","t":"أوقف المركبة مرة واحدة (لمدة 3-2 ثانية) قبل أن تنعطف نحو اليمين","b":false},{"k":"li","t":"تحرك ببطء عند الانعطاف نحو اليمين (يجب أن تكون سرعتك أقل من 15 كم / ساعة)","b":false},{"k":"page","p":133},{"k":"p","t":"لا يسمح لك بالانعطاف نحو اليمين عند وجود ضوء أحمر","b":true},{"k":"li","t":"إذا كان هناك مسار معين (مسار آخر ) للانعطاف إلى اليمين (في هذه الحالة عليك أن تأخذ ذلك المسار ولا يسمح لك بالانعطاف يمينا عند ذلك التقاطع)","b":false},{"k":"li","t":"إذا كانت هناك إشارة تحظر الانعطاف بوجود الضوء الأحمر","b":false},{"k":"remember","t":" التقاط صورة من قبل كاميرا «الرصد الألي» لا يعني بالضرورة فرض عقوبة عليك، حيث يتم فحص كل صورة تلتقطها الكاميرات يدويا بواسطة الموظفين قبل فرض العقوبة. إذا التزمت بالقواعد الواردة أعلاه، لا تقلق."}]},{"id":"hb-police","title":"التقاطعات المنظمة من قبل رجل المرور","from":134,"to":134,"b":[{"k":"page","p":134},{"k":"h3","t":"1،2 التقاطعات المنظمة من قبل رجل المرور (إشارات يدوية)"},{"k":"p","t":"إذا وصلت إلى تقاطع ينظمه رجل المرور يقوم بتوجيه حركة المرور، فيجب أن تلتزم بإشارات وتعليمات رجل المرور، لأنه يتمتع بأولوية قصوى ويجب احترام تعليماتهم.","b":false}]},{"id":"hb-stopgive","title":"إشارات «قف» و«أعط حق الأولوية»","from":135,"to":136,"b":[{"k":"page","p":135},{"k":"h3","t":"1،3 إشارات المرور «قف» و»أعط حق الأولوية»"},{"k":"p","t":"إشارة قف يجب على السائق توقيف المركبة وقوفا تام . تذكر أن تتوقف لمدة 3 ثوان بهدف مراقبة حركة المرور أو مستعملي الطريق الآخرين من جميع الجهات","b":true},{"k":"p","t":"إشارة حق الأولوية أعط حق الأولوية للسائقين الآخرين. إذا رأيت أي مركبة تقترب من مفترق الطرق، عليك التقليل من سرعتك، والتوقف إذا لزم الأمر للسماح لها بالمرور. يجب على السائق إعطاء حق الأولوية لحركة المرور الأخرى على الطريق تكون الأولوية لمستعملي الطرق الذين يقتربون من اليمين أو اليسار.","b":true},{"k":"page","p":136},{"k":"h3","t":"يمكن التنبيه لكلا اللافتتين بإشارات تحذير."},{"k":"p","t":"يتم التنبيه عن علامة المرور قف بواسطة علامة التحذير هذه يتم التنبيه عن علامة المرور الخاصة بحق الأولوية بواسطة علامة التحذير هذه:","b":false},{"k":"p","t":"وردت خصائص هاتين الإشارتين والغرض منهما في الوحدة الثانية.","b":false}]},{"id":"hb-priority","title":"قواعد الحق في الطريق أو قواعد الأولوية","from":137,"to":161,"b":[{"k":"page","p":137},{"k":"h3","t":"1،4 قواعد الحق في الطريق أو قواعد الأولوية"},{"k":"p","t":"يجب مراعاة قواعد الأولوية في التقاطعات التي لا يتم التحكم فيها بواسطة إشارة المرور أو بواسطة رجل المرور:","b":false},{"k":"p","t":"إتوضع للتحذير من وجود تقاطع امامك بواسطة الإشارات الضوئية أو تعليمات رجل المرور:","b":false},{"k":"page","p":138},{"k":"h3","t":"قواعد الأولوية"},{"k":"p","t":"مركبات الطوارئ","b":true},{"k":"li","t":"يجب إعطاء حق الأولوية لمركبات الطوارئ أثناء أداء مهامها.","b":false},{"k":"li","t":"مركبات الطوارئ لها الأولوية دائما وأبدا","b":false},{"k":"li","t":"يجب على السائق إخلاء الطريق لعبور مركبات الطوارئ في أسرع وقت ممكن","b":false},{"k":"page","p":139},{"k":"p","t":"قواعد عبور التقاطعات حيث لا يوجد طريق أفضل من الطرق الأخرى (الطرق المتساوية)","b":true},{"k":"li","t":"الأولوية للمركبة الأقرب من التقاطع","b":false},{"k":"li","t":"قاعدة اليمين قبل اليسار","b":false},{"k":"page","p":140},{"k":"h3","t":"أولوية المركبة الأقرب للتقاطع"},{"k":"p","t":"إذا اقتربت مركبتان من تقاطع متساو لكن ليس في نفس الوقت، فإن السيارة الأقرب للتقاطع (المركبة التي تدخل في التقاطع أولا) لها حق الأولوية.","b":false},{"k":"p","t":"المركبة البيضاء (ب) هي الأقرب وستدخل التقاطع أولا، وبالتالي تكون الأولوية للمركبة البيضاء (ب).","b":false},{"k":"p","t":"على الرغم من أن المركبة الأقرب للتقاطع لها الأولوية على المركبات الأخرى، يجب على سائق المركبة المتقدمة مراقبة حركة المرور وتقييم الوضع (على سبيل المثال، إذا كان هناك تغيير في مسافة المركبة الأخرى). يجب ألا يتوقف السائق الأقرب أو يغير اتجاهه بطريقة تتسبب بوقوع حادث.","b":false},{"k":"p","t":"مثال: السيارة البيضاء (أ) لها حق الأولوية","b":true},{"k":"page","p":141},{"k":"h3","t":"قاعدة اليمين قبل اليسار"},{"k":"p","t":"إذا اقتربت مركبتان من تقاطع متساو في نفس الوقت، فإن المركبة على الجانب الأيمن لها حق الأولوية.","b":false},{"k":"p","t":"الأهم هو من أي اتجاه تقترب المركبات من التقاطع وليس الاتجاه الذي تتجه إليه.","b":false},{"k":"p","t":"تقترب المركبتان من التقاطع في نفس الوقت على طرق متساوية، وهنا يكون حق الأولوية للمركبة البيضاء (أ) التي تسير على الجانب الأيمن.","b":false},{"k":"p","t":"مثال: هنا المركبة الرمادية (ب) لها حق الأولوية وليس المركبة البيضاء في الأمثلة الثلاثة أدناه.","b":true},{"k":"page","p":142},{"k":"h3","t":"القيادة نحو الأمام"},{"k":"p","t":"الخطوة 1 المركبات التي تقود نحو الأمام بخط مستقيم لها الأولوية على المركبات التي تغير مسارها.","b":true},{"k":"p","t":"الخطوة 2 المركبة البيضاء (ب) لها الأولوية على المركبة الحمراء (أ) التي تستعد للانعطاف نحو اليسار.","b":true},{"k":"page","p":143},{"k":"p","t":"القيادة نحو الأمام – حركة موازية","b":true},{"k":"p","t":"الخطوة 1 بالنسبة للمركبات التي تسير بخط متواز، يكون للسائق الذي يسير بشكل مستقيم الأولوية على السائق الذي يرغب في تغيير الاتجاه.","b":true},{"k":"p","t":"الخطوة 2 المركبة البيضاء (ب) لها الأولوية على المركبة الحمراء (أ) لأن المركبة (ب) تسير بشكل مستقيم بينما المركبة ( أ ) تغير الاتجاه.","b":true},{"k":"page","p":144},{"k":"p","t":"القيادة نحو الأمام – حركة موازية","b":true},{"k":"p","t":"الخطوة 1 السائق الذي يقود مركبته نحو الأمام بشكل مستقيم لديه الحق في الأولوية في تجاوز السائقين الذين يغيرون اتجاههم.","b":true},{"k":"p","t":"الخطوة 2 لدى سائق المركبة البيضاء (ج) الذي يقود سيارته مباشرة نحو الأمام الأولوية في العبور وتجاوز سائق المركبة الحمراء (أ) الذي يغير الاتجاه.","b":true},{"k":"page","p":145},{"k":"p","t":"القيادة نحو الأمام – طريق مغلقة","b":true},{"k":"p","t":"الخطوة 1 إذا التقى سائقان في طريق ذو اتجاهين مغلق (بشكل جزئي)، تكون الأولوية للسائق الذي تكون الطريق أمامه مفتوحة على الجانب الأيمن.","b":true},{"k":"p","t":"الخطوة 2 لدى سائق المركبة البيضاء (ب) حق الأولوية على سائق المركبة الحمراء (أ) لأن الطريق أمام سائق السيارة البيضاء مفتوح على الجانب الأيمن.","b":true},{"k":"p","t":"يمكن للسائق استخدام الجانب الأيسر من الطريق إذا كان الجانب الأيمن مغلقا بسبب أعمال البناء أو لأسباب أخرى. عندما يتم إغلاق جزء من طريق ذو اتجاهين، يجب على السائق الامتثال لتعليمات ادارة المرور أو قوات الأمن الأخرى أو عمال الطرق. إذا التقى سائقان في طريق مغلق (بشكل جزئي)، فيجب على كليهما تقليل السرعة والتوقف إذا كان ذلك ضروريا لتجنب وقوع حادث.","b":false},{"k":"page","p":146},{"k":"p","t":"القيادة صعودا على طريق جبلي على طريق منحدر بشكل حاد، يجب على السائق الذي يتجه نحو المنحدر نزولاا أن يقترب قدر الإمكان من الحافة اليمنى للمسار، ويجب عليه السماح بمرور المركبات الصاعدة دون صعوبات تذكر، وإذا لزم الأمر ينبغي أن يتوقف السائق بشكل تام. استثناء: في حال وجود منطقة لوقوف المركبات في حالات الطوارئ على جانب السائق الذي يحاول الصعود، فيجب أن ينتظر السائق ويسمح بمرور المركبة نحو المنحدر نزولا.","b":true},{"k":"page","p":147},{"k":"p","t":"دخول الطريق الرئيسي","b":true},{"k":"page","p":148},{"k":"p","t":"الطريق الرئيسي","b":true},{"k":"p","t":"الخطوة 1 لدى السائق على الطريق الرئيسي حق الأولوية مقارنة بالسائق القادم من طريق ثانوي.","b":true},{"k":"p","t":"الخطوة 2 لدى سائق المركبة البيضاء (ب) حق الأولوية لأنه على الطريق الرئيسي.","b":true},{"k":"page","p":149},{"k":"p","t":"الطريق الرئيسي عند الدخول من طريق ثانوية إلى الطريق الرئيسي، يجب على السائق التأكد من خلو الطريق وإعطاء الأولوية للمركبات التي تقود على طول الطريق الرئيسي. يجب على السائق على الطريق الرئيسي إعطاء السائق القادم من الطريق الثانوي فرصة للدخول.","b":true},{"k":"p","t":"الخطوة 1 عند الدخول من طريق ثانوي، يجب على السائق إعطاء الأولوية للسائقين على الطريق الرئيسي.","b":true},{"k":"p","t":"الخطوة 2 يقود سائق المركبة البيضاء (ب) مركبته على الطريق الرئيسي ولهذا له الأولوية على المركبة الحمراء (أ).","b":true},{"k":"page","p":150},{"k":"p","t":"الطريق الرئيسي – السلوك التعاوني الصحيح يعطي سائق المركبة البيضاء (ب) سائق المركبة الحمراء (أ) الفرصة لدخول الطريق الرئيسي.","b":true},{"k":"page","p":151},{"k":"p","t":"الخروج من الطريق الرئيسي","b":true},{"k":"page","p":152},{"k":"p","t":"الطريق الرئيسي","b":true},{"k":"p","t":"الخطوة 1 تعطى أولوية المرور للمركبات الخارجة من الطريق الرئيسي إلى طريق الخدمة.","b":true},{"k":"p","t":"الخطوة 2 عند القدوم من الطريق الرئيسي، يملك سائق المركبة البيضاء (ب) حق الأولوية على المركبة الحمراء (أ).","b":true},{"k":"page","p":153},{"k":"p","t":"الطريق الرئيسي – السلوك التعاوني عند القدوم من الطريق الرئيسي، يملك سائق المركبة البيضاء (ب) الأولوية على المركبة الحمراء (أ). إذا كان ذلك ممكن ، يجب على سائق المركبة الحمراء فتح الطريق أمام السيارة البيضاء.","b":true},{"k":"page","p":154},{"k":"p","t":"تقاطع مع دوار","b":true},{"k":"page","p":155},{"k":"p","t":"تقاطع دوار يجب على السائق الذي يقترب من التقاطع الذي يشكل تقاطع دائري إعطاء الأولوية للمركبات التي تسير حول الدوار المركبة البيضاء تقود في دوار، لذلك فإن سائق المركبة البيضاء (ب) له الأولوية على المركبة الحمراء (أ).","b":true},{"k":"page","p":156},{"k":"p","t":"الدوران على شكل حرف (U) عند تقاطع","b":true},{"k":"page","p":157},{"k":"p","t":"الدوران على شكل حرف (U) عند تقاطع يسمح للسائق بالدوران للخلف على شكل حرف (U) فقط عند التقاطعات إذا لم تكن هناك إشارة مرور أو إشارة ضوئية تمنع ذلك. تعطى الأولوية للمركبات القادمة من أي اتجاه آخر. المركبة الحمراء (أ) سوف تقوم بالدوران للخلف على شكل حذوة فرس، وبالتالي فإن المركبة البيضاء والمركبة الرمادية (ب + ج) لهما حق الأولوية. تدخل المركبة البيضاء التقاطع أولاا – تكون أول من يسمح لها بالمرور","b":true},{"k":"page","p":158},{"k":"p","t":"الدوران الى الخلف المغلق عند الدخول إلى منعطف على شكل حذوة فرس مغلق، يجب إعطاء الأولوية لجميع المركبات التي تقترب من المنعطف والانتقال إلى المسار الأول عندما تكون الطريق خالية من المركبات. لا تستخدم ممرات وقوف المركبات أو الأرصفة للانعطاف على شكل حذوة فرس.","b":true},{"k":"p","t":"الدوران الى الخلف المفتوح عند الدخول إلى منعطف مفتوح على شكل حذوة فرس، يجب إعطاء الأولوية لكافة المركبات التي تقترب من المنعطف والانتقال إلى المسار الثاني عندما يكون الطريق خالي من المركبات للسماح للمركبات القادمة من مفترق الطرق بالدخول .","b":true},{"k":"page","p":159},{"k":"h3","t":"الدوران الى الخلف المحمي"},{"k":"p","t":"قواعد السلوك العامة عند التقاطعات","b":true},{"k":"li","t":"على السائقين الاقتراب من التقاطع بحذر وتقليل السرعة بشكل يسمح لهم بالتوقف قبل الوصول إلى المعبر في حال كان لمستعملي الطريق الآخرين أولوية العبور.","b":false},{"k":"li","t":"إذا لم يتمكن السائقون من عبور التقاطع، فعليهم التوقف قبل الوصول إلى المعبر، حتى إذا كان لديهم حق أولوية أو في ظل وجود الضوء الأخضر. إذا كان هناك خطر أن يعلق السائق في التقاطع (بسبب تباطؤ حركة المرور أو توقفها)، يجب عليه تجنب دخول التقاطع منذ البداية.","b":false},{"k":"page","p":160},{"k":"h3","t":"أهمية قواعد الأولوية"},{"k":"p","t":"تهدف قواعد الأولوية إلى توضيح متى يجب على السائقين إعطاء حق الأولوية لمستعملي الطريق الآخرين. تلعب هذه القواعد دورا حيويا في ضمان السلامة على طرق المملكة العربية السعودية. يمكن أن يساهم الالتزام بهذه القواعد ليس فقط في ضمان سلامة الحركة المرورية بل أيضا في الحد من حوادث السير والتقليل من عواقبها المأساوية. لذلك من المهم ان يكون جميع السائقون على دراية بهذه القواعد من أجل الامتثال لها بشكل تام كلما وحيثما كان ذلك ضروريا بدون أي تردد.","b":false},{"k":"h3","t":"الالتزام بقواعد حق الأولوية في الحالات غير الواضحة"},{"k":"p","t":"إذا واجه السائق وضعا لا يكون فيه من الواضح أي مركبة لها حق الأولوية، على سبيل المثال:","b":true},{"k":"li","t":"عندما تتوقف أكثر من مركبة عند نقطة العبور","b":false},{"k":"li","t":"عند وجود مستخدم آخر للطريق غير قادر بوضوح على الالتزام بقواعد الأولوية","b":false},{"k":"p","t":"في الحالات المذكورة أعلاه، فمن المستحسن","b":true},{"k":"li","t":"التواصل بصريا مع مستخدم الطريق الآخر","b":false},{"k":"li","t":"الامتناع عن استخدام حقك في الطريق وإفساح المجال للآخرين إذا كان ذلك يساعد في تجنب وقوع حادث.","b":false},{"k":"remember","t":" من أجل الشعور بشكل أفضل بأهمية قواعد حق الأولوية، نقترح عليك العودة إلى الوحدة الأولى وإلقاء نظرة على العقوبات."},{"k":"page","p":161},{"k":"h3","t":"ما يجب القيام به عند المعابر"},{"k":"p","t":"دخول المعبر النظر حولك تقييم الوضع اتخاذ قرار التصرف","b":true},{"k":"p","t":"الاقتراب من المعابر التحقق من المرايا إعطاء إشارة تموضع المركبة السرعة النظر حولك","b":true},{"k":"h3","t":"ماذا تفعل قبل الدخول إلى مفترق طرق"},{"k":"p","t":"النظر حولك: تحقق من كلا الجانبين وتحقق من عدم وجود آخرين على الطريق","b":true},{"k":"p","t":"تقييم الوضع: السرعة، العمر ، الانتباه، النية، المسافات","b":true},{"k":"p","t":"اتخاذ قرار: هل من الآمن مواصلة السير ودخول المفترق؟","b":true},{"k":"p","t":"التصرف: هل أنتظر أم أتحرك","b":true}]},{"id":"hb-pedx","title":"معابر المشاة","from":162,"to":162,"b":[{"k":"page","p":162},{"k":"h2","t":"2. معابر المشاة"},{"k":"p","t":"أين يمكنك رؤية هذه الإشارات؟","b":false},{"k":"p","t":"هل تتذكر كيف تتصرف عند معابر المشاة؟","b":false},{"k":"p","t":"عربات الركاب والدراجات الهوائية تعطى عربات الركاب والدراجات الهوائية حق الأولوية على مركبات النقل البطيئة الأخرى","b":false}]},{"id":"hb-rail","title":"معابر السكك الحديدية","from":163,"to":165,"b":[{"k":"page","p":163},{"k":"h2","t":"3. معابر السكك الحديدي"},{"k":"page","p":164},{"k":"p","t":"مركبات السكك الحديدية لها الأولوية على المركبات الأخرى. على السائقين إخلاء خط سكة الحديد على الفور عندما تقترب عربة السكك الحديدية","b":true},{"k":"p","t":"تأمين معابر السكك الحديدية والتحذير المسبق","b":true},{"k":"li","t":"الحواجز","b":false},{"k":"li","t":"حارس – يجب على سائقي المركبات الالتزام بمكان الحواجز أو الحارس","b":false},{"k":"li","t":"الإشارات الضوئية: الأحمر أو الأصفر – تشير إلى أن القطار يقترب. يجب على سائقي المركبات عدم عبور خط السكة الحديدية.","b":false},{"k":"li","t":"إشارات الجرس – تحذير صوتي من اقتراب القطار. يجب على سائقي المركبات عدم عبور خط السكة الحديدية.","b":false},{"k":"p","t":"يجوز عبور ممر السكك الحديدية فقط عندما تشير الإشارة إلى أنه آمن وعلى السائق التأكد قبل ذلك من عدم وجود أي قطار يقترب.","b":false},{"k":"p","t":"إذا توقفت حركة المرور أو تباطأت وتصبح احتمالية التوقف عند ممر السكك الحديدية تشكل خطرا، فيجب على السائق عدم دخول معبر السكة الحديدية.","b":false},{"k":"page","p":165},{"k":"h3","t":"التوقف أمام معبر للسكك الحديدية"},{"k":"p","t":"يجب على سائقي المركبات التوقف قبل إشارة X","b":true},{"k":"li","t":"عندما يقترب القطار","b":false},{"k":"li","t":"عند وجود إشارة الضوء الأحمر أو الأصفر","b":false},{"k":"li","t":"عندما تتحرك البوابات أو عندما تكون مغلقة","b":false},{"k":"li","t":"عندما يشير أحد الحراس إلى التوقف","b":false},{"k":"li","t":"إذا لم تسمح حركة المرور بالعبور الكامل للمعبر","b":false},{"k":"p","t":"في معابر السكك الحديدية أو قضبان السكة الحديدية يمنع","b":true},{"k":"li","t":"التوقف على القضبان","b":false},{"k":"li","t":"وقوف المركبات على السكك الحديدية","b":false},{"k":"li","t":"القيادة على طول القضبان","b":false},{"k":"h3","t":"التصرف عند العبور"},{"k":"p","t":"انتظر حتى يتم فتح البوابات بشكل تام ويتم إطفاء الضوء الأحمر قبل الدخول إلى معبر السكة الحديدية.","b":false}]},{"id":"hb-u5","title":"الوحدة الخامسة: سرعة القيادة والقيادة واحدا تلو الآخر","from":166,"to":167,"b":[{"k":"page","p":166},{"k":"h2","t":"الوحدة الخامسة سرعة القيادة / القيادة واحدا تلو الآخر"},{"k":"page","p":167}]},{"id":"hb-limits","title":"محددات السرعة العامة","from":168,"to":174,"b":[{"k":"page","p":168},{"k":"h2","t":"1. محددات السرعة العامة"},{"k":"h3","t":"المركبات الصغيرة"},{"k":"p","t":"إذا لم يكن هناك أي مؤشر على وجود محدد آخر للسرعة، يجب ألا يتجاوز سائقو المركبات الصغيرة الحد الأقصى التالي للسرعة","b":false},{"k":"li","t":"الطرق الفرعية حسب السرعة المحددة للطريق","b":false},{"k":"li","t":"الطرق الرئيسية حسب السرعة المحددة للطريق","b":false},{"k":"page","p":169},{"k":"h3","t":"المركبات الكبيرة"},{"k":"p","t":"إذا لم يكن هناك أي مؤشر على وجود محدد آخر للسرعة، يجب ألا يتجاوز سائقو المركبات الكبيرة الحد الأقصى التالي للسرعة","b":false},{"k":"li","t":"طرق المدينة داخل المدن 50 كم / ساعة حد أقصى","b":false},{"k":"li","t":"خارج حدود المدينة / حدود مفتوحة حسب سرعة الطريق","b":false},{"k":"page","p":170},{"k":"p","t":"يمكن أن تشير إشارات المرور أيضا إلى حدود السرعة الأخرى.","b":true},{"k":"remember","t":" إذا لم يكن هناك محدد آخر للسرعة، يجب عليك الالتزام بمحدد السرعة بعد هذه الإشارة"},{"k":"p","t":"كما توجد أيضا إشارة مرور تشير إلى نهاية حد السرعة:","b":true},{"k":"remember","t":" لا تشعر بأنك مجبر على القيادة بهذه السرعة، هذه الإشارات تظهر لك فقط الحد الأقصى!"},{"k":"page","p":171},{"k":"p","t":"الحالات التي يجب فيها تقليل السرعة عن الحد الأدنى للسرعة","b":true},{"k":"li","t":"في الليل","b":false},{"k":"li","t":"عند ظهور أشعة شمس قوية","b":false},{"k":"page","p":172},{"k":"p","t":"الحالات التي يجب فيها تقليل السرعة عن الحد الأدنى للسرعة","b":true},{"k":"li","t":"أثناء الضباب","b":false},{"k":"li","t":"أثناء المطر","b":false},{"k":"li","t":"أثناء العواصف الرملية وكذلك حسب حالة الطريق","b":false},{"k":"page","p":173},{"k":"p","t":"استثناء:","b":true},{"k":"p","t":"يمكن لمركبات الطوارئ تجاوز السرعة القصوى ولكن يجب ألا يعرض ذلك سلامة الآخرين للخطر.","b":false},{"k":"remember","t":" كن دائما على علم بما يحدث من حولك أثناء القيادة حتى يتسنى لك السماح لمركبات الطوارئ بالمرور بسهولة."},{"k":"page","p":174},{"k":"p","t":"يمكن لإشارات المرور أن تشير أيضا إلى الحد الأدنى للسرعات.","b":true},{"k":"p","t":"الحد الأدنى للسرعة نهاية الحد الأدنى للسرعة","b":false},{"k":"li","t":"تشير ھذه الإشارات للسائق بعدم القیادة بسرعة أبطأ من السرعة الدنیا المقترحة.","b":false},{"k":"li","t":"استثناء: يمكن للسائق القيادة بسرعة أبطأ من السرعة الدنيا في حال تطلب ذلك موقف ما أو إجراءات السلامة.","b":false}]},{"id":"hb-choosespeed","title":"معايير اختيار سرعة القيادة","from":175,"to":185,"b":[{"k":"page","p":175},{"k":"h2","t":"2. معايير لاختيار سرعة القيادة"},{"k":"p","t":"على السائق دائما ضبط سرعته وفقا للظروف العامة وظروف الطريق، بغض النظر عن السرعة القصوى المسموح بها، ويجب عليه ضمان سلامته وسلامة من معه في المركبة وسلامة مستعملي الطريق الآخرين في جميع الأوقات، ويجب عليه كذلك تكييف سرعة المركبة لتكون قادرة على التوقف في الوقت المناسب في حال وجود إشارة توقف أو حاجز.","b":false},{"k":"page","p":176},{"k":"p","t":"يجب عليك تقليل سرعة القيادة الخاصة بك:","b":true},{"k":"li","t":"عند الاقتراب من التقاطعات أو أي نوع من المعابر","b":false},{"k":"li","t":"قبل المنحنيات","b":false},{"k":"li","t":"عند عبور الجسور","b":false},{"k":"li","t":"عند عبور معابر السكك الحديدية","b":false},{"k":"li","t":"عند القيادة عبر الأنفاق","b":false},{"k":"li","t":"عند تدني مستوى الرؤية","b":false},{"k":"li","t":"على الطرق الزلقة (وجود المياه والرمل والثلج، ...)","b":false},{"k":"page","p":177},{"k":"p","t":"ما مدى السرعة التي تعتقد أنك يمكن أن تسير بها في هذه الحالات المحددة؟","b":true},{"k":"p","t":"بعد هذه الإشارة؟ في هذا المنحنى؟","b":false},{"k":"p","t":"في هذه الحالة؟ على هذه الطريق؟","b":false},{"k":"page","p":178},{"k":"remember","t":" لا يوجد إجابة واحدة صحيحة لأي من الحالات المعروضة السابقة، حيث توفر الصور مجرد محفز للمناقشة من أجل توضيح ما يلي:"},{"k":"p","t":"يجب عليك تقييم كل حالة على حدة. إذا كنت تشعر بأنك غير متأكد حيال إحدى تلك الحالات، فمن الأفضل أن تقود بشكل أبطأ من ذلك بقليل.","b":false},{"k":"page","p":179},{"k":"p","t":"للقيادة بسرعة آمنة، يجب عليك مراعاة ما يلي:","b":true},{"k":"li","t":"حركة المرور","b":false},{"k":"li","t":"إمكانية وجود عوائق على الطريق أو غيرك من مستعملي الطريق الآخرين","b":false},{"k":"li","t":"ظروف الطريق","b":false},{"k":"li","t":"حالة المركبة الخاصة بك","b":false},{"k":"remember","t":" يجب الحرص على عدم تعريض الناس أو الحيوانات للخطر، وتأكد دائما من أنه يمكنك التوقف في الوقت المناسب!"},{"k":"page","p":180},{"k":"p","t":"أمثلة أخرى حيث من المهم تقليل السرعة:","b":true},{"k":"li","t":"إذا كان الطريق ليس طريقا سريع","b":false},{"k":"li","t":"في الأماكن المتعرجة من الطريق","b":false},{"k":"li","t":"خلال حركة المرور المزدحمة","b":false},{"k":"li","t":"عند الاقتراب من المطبات","b":false},{"k":"li","t":"عند الاقتراب أو المرور بمجموعة من المشاة","b":false},{"k":"li","t":"عند الاقتراب أو المرور من الحيوانات خاصة عندما تظهر على الحيوانات علامات قلق وتوتر","b":false},{"k":"p","t":"يحظر تسابق المركبات على الطرق العامة داخل حدود المدينة أو خارجها!","b":true},{"k":"page","p":181},{"k":"p","t":"السرعة تقتل!","b":true},{"k":"remember","t":" من الواضح أن السائق كان يقود مركبته بسرعة عالية جدا."},{"k":"page","p":182},{"k":"p","t":"«التفحيط» هو شكل غير قانوني من سباقات الطرق التفحيط هو شكل من أشكال السباقات بحيث يتم قيادة المركبات بسرعات عالية للغاية تصل إلى حوالي 160 إلى 260 كم في الساعة على الطرق السريعة الواسعة وفي الوقت ذاته تأرجح المركبة إلى اليمين واليسار، وغالبا ما يقود السائقون مركباتهم في هذه الحالة بالقرب من حركة المرور والحواجز وبشكل خطير بالقرب من المتفرجين الذين يشاهدون ما يحصل من على جوانب الطريق دون أي حماية. مع العلم أن العديد من حوادث المرور المروعة تقع نتيجة التفحيط.","b":true},{"k":"page","p":183},{"k":"p","t":"مثال حي لإثبات مدى تأثير السرعة ليس عليك أن تدخل في سباق على تعريض حياتك للخطر. فالقيادة بسرعة لا تزيد عن 10 كم في الساعة عن الحد المسموح به وعدم ربط أحزمة الأمان كافية لإحداث إصابة خطيرة.","b":true},{"k":"p","t":"تخيل: أنت تسير بسرعة 50 كم / ساعة وفجأة تخرج عليك شاحنة من مفترق الطرق أمامك، تخاف فتقوم بالضغط على الفرامل بقوة وتستطيع التوقف في الوقت المناسب.","b":false},{"k":"p","t":"الآن تخيل ما يلي: أنت تسير بسرعة 60 كم / ساعة (أي بمقدار 10 كم / ساعة أسرع من الحالة الأولى) وفجأة تخرج عليك الشاحنة مرة أخرى من مفترق الطرق أمامك، تشعر بالخوف مجددا فتقوم بالضغط على الفرامل بقوة لكنك هذه المرة لا تستطيع التوقف في الوقت المناسب.","b":false},{"k":"p","t":"سوف تضرب الشاحنة بسرعة 40 كم / ساعة في المثال الثاني! إذا كنت أنت أو أحد الركاب لا ترتدون أحزمة الأمان، فإن تأثير القوة البدنية كان سيبدو كما لو كنت قد قفزت من نافذة من الطابق الثالث وضربت الأرض بعد سقوطك من ارتفاع 6.5 متر فقط لأنك كنت تقود بسرعة أكبر من السرعة في المثال الأول بمقدار 10 كم في الساعة.","b":false},{"k":"page","p":184},{"k":"p","t":"من ناحية أخرى، فإنه يحظر عليك أيضا","b":true},{"k":"li","t":"عرقلة سير المركبات الأخرى عن طريق القيادة ببطء شديد دون أي سبب مقنع","b":false},{"k":"li","t":"تقليل السرعة بشكل مفاجئ أو الفرملة بقوة ما لم يكن ذلك ضروريا لأسباب تتعلق بالسلامة","b":false},{"k":"p","t":"في حال قمت بتقليل السرعة، فيجب عليك الإشارة إلى ذلك في الوقت المناسب","b":true},{"k":"li","t":"أضواء الفرامل في الجزء الخلفي من المركبة","b":false},{"k":"li","t":"إشارات اليد","b":false},{"k":"page","p":185},{"k":"p","t":"يجب على السائق والركاب أن يستخدموا حزام الأمان","b":false},{"k":"remember","t":" في حالة وقوع حادث، يمكن للأشخاص أو الأشياء غير المؤمنة أن تلحق إصابات خطيرة بالركاب الآخرين!"}]},{"id":"hb-distance","title":"مسافة الأمان","from":186,"to":188,"b":[{"k":"page","p":186},{"k":"h2","t":"3. مسافة الأمان"},{"k":"p","t":"يجب أن يحافظ السائقون الذين يقودون خلف المركبات الأخرى أو يستعدون لتجاوز المركبات الأخرى أمامهم على مسافة كافية لتجنب وقوع حادث.","b":false},{"k":"page","p":187},{"k":"h3","t":"مسافة الأمان"},{"k":"p","t":"إذا تباطأ سائق المركبة الأمامية فجأة أو توقف بسبب حالة طارئة، فيجب أن يكون السائق في المركبة الخلفية قادرا على الاستجابة في الوقت المناسب لإيقاف مركبته بأمان.","b":false},{"k":"p","t":"أسباب زيادة مسافة الامان","b":true},{"k":"li","t":"ظروف الطريق السيئة (على سبيل المثال طريق مبلل أو توجد عليه رمال)","b":false},{"k":"li","t":"القيادة خلف المركبات في طريق ذات مسار واحد (مثل الدراجات الآلية)","b":false},{"k":"li","t":"قيادة مركبة محملة بشكل كبير","b":false},{"k":"page","p":188},{"k":"p","t":"مخاطر القيادة خلف المركبات الأخرى دون ترك مسافة","b":true},{"k":"remember","t":" القيادة دون ترك مسافة أمان تزيد من احتمالية الاصطدام بالمركبات التي تسير أمامك. لماذا ا؟ لأنه لا يوجد لديك وقت كاف للتوقف عند قيام سائق المركبة الأمامية بالضغط على الفرامل"}]},{"id":"hb-behaviour","title":"السلوك الصحيح","from":189,"to":191,"b":[{"k":"page","p":189},{"k":"h2","t":"4. السلوك الصحيح"},{"k":"p","t":"هذا السائق يقود مركبته دون ترك مسافة أمان أقل مسافة للقيادة خلف مركبة أخرى هي ثانيتين!","b":false},{"k":"page","p":190},{"k":"p","t":"قاعدة الثانيتين (ألف وواحد ألف وأثنان) مدتها ثانيتين يجب عليك التحقق بانتظام من المسافة التالية، خاصة عند القيادة بسرعات أعلى خلف المركبات الأخرى (على سبيل المثال على الطريق السريع أو المفتوح).","b":true},{"k":"p","t":"الخطوة 1 ابحث عن نقطة مرجعية مثل إشارة مرور أو شجرة ، أو سارية قريبة من الطريق أو يمكنك البحث عن علامة أو ظل على الطريق.","b":true},{"k":"p","t":"الخطوة 2 ابدأ بعد الثواني عندما يكون الجزء الخلفي من المركبة التي تسير أمامك عند تلك النقطة المرجعية.","b":true},{"k":"p","t":"الخطوه 3 واصل العد حتى تصل مقدمة مركبتك إلى النقطة المرجعية. يجب أن تعد على الأقل ثانيتين، وإلا فإن المسافة بينك وبين المركبة الأمامية ليست آمنة.","b":true},{"k":"p","t":"الخطوة 1 الخطوة 2 الخطوة 3","b":false},{"k":"page","p":191},{"k":"remember","t":" يجب ترك مسافة أطول في حال الأحوال الجوية المتغيرة مثل العواصف، الغبار، المطر، وحالة الطريق السيئة."}]},{"id":"hb-eco","title":"القيادة الاقتصادية","from":192,"to":193,"b":[{"k":"page","p":192},{"k":"h3","t":"أهمية الحفاظ على مسافات تتابع كبيرة:"},{"k":"p","t":"من خلال تطبيق أسلوب القيادة والنظر إلى الأمام في الوقت ذاته تجد أن لديك المزيد من الوقت للاستجابة مع المواقف والأخطار الناشئة، فالمطلوب هو ضغط أقل على دواسة الوقود والحصول على نسبة أكبر من السلامة والأمان.","b":true},{"k":"h2","t":"5. القيادة الاقتصادية"},{"k":"p","t":"يعد أسلوب القيادة والنظر إلى الأمام أحد العناصر الرئيسية للقيادة الاقتصادية. وهذا يعني رفع قدمك عن دواسة البنزين وجعل السيارة تتباطئ دون الضغط على دواسة الفرامل، على سبيل المثال، إشارة مرور حمراء وبالتالي لا يتم استخدام الوقود أثناء الاقتراب من إشارة المرور وهذا يقلل أيضا من تآكل الفرامل.","b":true},{"k":"p","t":"الشيء الذي ينبغي تجنبه هو إيقاف السيارة بلاداع حيث أن تشغيلها مجددا يتطلب الكثير من الطاقة. لكن في حال كان إيقافها لا بد منه وكانت السيارة تحتوي على وظيفة التشغيل/الإيقاف التلقائي، يمكنك عندئذ التوقف لتوفير الوقود، حيث أن هذه الميزة تقوم بإيقاف تشغيل المحرك عند إيقاف السيارة ويتم إعادة تشغيل المحرك تلقائيا بمجرد رفع قدمك عن دواسة الفرامل. أما في حال قيادة السيارة دون استخدام وظيفة التشغيل/الإيقاف، يمكنك توفير الوقود من خلال إيقاف تشغيل المحرك إذا كانت فترة التوقف أطول من 20 ثانية.","b":false},{"k":"page","p":193},{"k":"h3","t":"أمور أخرى يجب وضعها في الاعتبار عند محاولة توفير الوقود:"},{"k":"li","t":"السرعة: السرعة بين 70 إلى 90 كم/ساعة توفر في استهلاك الوقود، لذا يجب تجنب القيادة عند أي سرعة تتجاوز 100 كم/ساعة عند محاولة توفير الوقود","b":false},{"k":"li","t":"التسارع: تجنب التسارع القوي","b":false},{"k":"li","t":"السرعة الثابتة: حاول القيادة بسرعة ثابتة من خلال استخدم نظام تثبيت السرعة قدر الإمكان","b":false},{"k":"li","t":"إفراغ الوزن الزائد","b":false},{"k":"li","t":"ضغط الإطارات: افحص ضغط الإطارات بشكل منتظم","b":false},{"k":"li","t":"تدفئة النافذة الخلفية: تستخدم حوالي 0.7 لتر وقود لكل 100 كيلومتر، وينبغي أن تستخدم فقط إذا كانت النافذة الخلفية ضبابية، ويجب التأكد من أنه لم يتم تشغيلها عن طريق الخطأ.","b":false},{"k":"li","t":"تكييف الهواء: لا تضبطه أبدا على درجات متدنية للغاية، بالإضافة إلى تشغيل زر إعادة تدوير الهواء، ويجب إغلاق النوافذ دائما عند تشغيل المكيف","b":false},{"k":"li","t":"النوافذ: أغلق النوافذ عند القيادة بسرعة 60 كم/ساعة بسبب مقاومة الهواء","b":false},{"k":"li","t":"المسافات القصيرة: تجنب يالقيادة لمسافات قصيرة واستخدم وسائل النقل البديلة بما في ذلك الدراجة ووسائل النقل العام أو المشي وما إلى ذلك","b":false},{"k":"li","t":"استخدم الوقود الصحيح للسيارة","b":false},{"k":"li","t":"تجنب ساعات الذروة والاختناقات المرورية قدر الإمكان","b":false},{"k":"li","t":"انطلق على الفور بعد تشغيل السيارة","b":false},{"k":"h3","t":"سلوكيات صديقة للبيئة"},{"k":"li","t":"غسل السيارة في محطة الغسيل الخاصة بهدف إعادة تدوير المياه","b":false},{"k":"li","t":"صيانة السيارة بانتظام - عند القيام بتغيير الزيت في المنزل، استخدم عبوة لجمع الزيت القديم وتخلص منه بالطريقة الصحيحة ولا تدعه يلوث الأرضية","b":false},{"k":"li","t":"مشاركة السيارة: أكبر عدد ممكن من الأشخاص في سيارة واحدة","b":false},{"k":"li","t":"تركيب منقي في السيارة إذا أمكن ذلك","b":false},{"k":"li","t":"شراء سيارة موفرة للوقود","b":false}]},{"id":"hb-u6","title":"الوحدة السادسة: التجاوز والسلوك العام","from":194,"to":195,"b":[{"k":"page","p":194},{"k":"h2","t":"الوحدة السادسة التجاوز و السلوك العام"},{"k":"page","p":195}]},{"id":"hb-near","title":"القيادة بالقرب من المركبات والأشياء الثابتة","from":196,"to":201,"b":[{"k":"page","p":196},{"k":"h2","t":"1. القيادة بالقرب من المركبات والأشياء الثابتة"},{"k":"p","t":"القيادة بالقرب من أشياء ثابتة مثل المركبات المتوقفة أو (مجموعات) من الأشخاص أو (قطيع من الحيوانات).","b":false},{"k":"page","p":197},{"k":"h3","t":"ممنوع المرور:"},{"k":"li","t":"في حال تم إعاقة مستعملي الطريق الآخرين أو تعرضهم للخطر","b":false},{"k":"li","t":"في حال التسبب بأضرار للأشياء الثابتة","b":false},{"k":"li","t":"في حال خروج الأشخاص أو دخولهم إلى مركبات السكك الحديدية على أحد جانبي الطريق","b":false},{"k":"page","p":198},{"k":"h3","t":"كيفية القيادة بالقرب من المركبات / العقبات الثابتة:"},{"k":"remember","t":" هل تتذكر كيفية تغيير المسار؟ هذا مشابه لذلك!"},{"k":"page","p":199},{"k":"h3","t":"كيفية القيادة بالقرب من المركبات / العقبات الثابتة:"},{"k":"p","t":"إذا كان هناك عائق في المسار الذي تسير به:","b":true},{"k":"p","t":"انظر : ما هذا؟ ما الذي حدث؟ قيم : هل هناك حركة قادمة؟ هل هناك مساحة كافية للمرور؟","b":true},{"k":"p","t":"قرر : قرري إما المرور أو التوقف تصرف : حسب قرارك: تحرك (ابدأ) أو توقفي","b":true},{"k":"p","t":"القيادة بالقرب من العقبة:","b":true},{"k":"p","t":"المرايا : قم بالتحقق من المرايا الداخلية ومرايا الجانب الأيسر لرؤية المركبات التي تسير خلفك (قد تكون على وشك تجاوزك أو السير خلفك مباشرة)","b":true},{"k":"p","t":"الإشارة: قم بإعطاء إشارة لليسار الكتف: تحقق من النقطة العمياء على الجانب الايسر لمركبتك السرعة: قم بتكييف السرعة (زيادة السرعة إذا كان من الممكن اجتياز العائق بسرعة، أو إبطاء السرعة","b":true},{"k":"p","t":"إذا كان العائق ضيق ) التحرك: انتقل إلى الجانب الأيسر وتأكد من وجود مسافة جانبية كافية للمرور عن العائق.","b":true},{"k":"p","t":"قم بالقيادة بسلاسة!","b":false},{"k":"page","p":200},{"k":"remember","t":" تذكر أن السائق الذي تكون الطريق مفتوحة على جانبه اليمين يكون له حق الأولوية!"},{"k":"page","p":201},{"k":"p","t":"القيادة بالقرب من المركبات المتوقفة:","b":true},{"k":"li","t":"تأكد من الابتعاد من الجانب عن المركبات المتوقفة","b":false},{"k":"li","t":"(بسرعة 50 كم / ساعة تحتاج إلى مسافة متر واحد تقريب )","b":false},{"k":"li","t":"في الطرق ذات الاتجاهين قد تضطر إلى إبطاء السرعة أو التوقف عند وجود حركة قادمة من الاتجاه الآخر","b":false},{"k":"li","t":"انتبه وكن حذرا للمركبات التي على وشك أن تتحرك.","b":false},{"k":"li","t":"تعتمد المسافة الجانبية المطلوبة على سرعة القيادة، فكلما كنت أسرع كلما زادت المسافة بينك وبين المركبات المتوقفة","b":false},{"k":"li","t":"عند سرعة 50 كم / ساعة فإن متر واحد هي مسافة جانبية آمنة وهي تقريبا المساحة اللازمة لفتح باب المركبة.","b":false}]},{"id":"hb-overtake","title":"تجاوز المركبات المتحركة","from":202,"to":203,"b":[{"k":"page","p":202},{"k":"h2","t":"2. تجاوز المركبات المتحركة"},{"k":"p","t":"تجاوز المركبات التي تسير في نفس الاتجاه على نفس الطريق.","b":true},{"k":"page","p":203},{"k":"remember","t":" عادة يجب تخطي المركبات الأخرى عن الجانب الأيسر للطريق."},{"k":"p","t":"يجوز لك تجاوز المركبات من خلال الجانب الأيمن للطريق في الحالات التالية:","b":true},{"k":"li","t":"إذا كان السائق الذي أمامك يشير إلى نيته في الانعطاف إلى اليسار","b":false},{"k":"li","t":"إذا كان الطريق مقسم إلى أكثر من مسارين متجه في نفس الاتجاه","b":false},{"k":"h3","t":"تصرف السائق الذي يتجاوز عنه الآخرون"},{"k":"p","t":"السائق الذي يتجاوز عنه الآخرون:","b":true},{"k":"li","t":"يجب ألا يزيد سرعته","b":false},{"k":"li","t":"يجب عليه القيادة أقصى الجانب الأيمن من الطريق","b":false},{"k":"li","t":"يجب أن يشير إلى السائق الآخر بإمكانية تجاوزه","b":false},{"k":"li","t":"يجب عليه التقليل من سرعته إذا تجاوزته مجموعة من المركبات","b":false}]},{"id":"hb-noovertake","title":"محظورات التجاوز","from":204,"to":209,"b":[{"k":"page","p":204},{"k":"h2","t":"3. محظورات التجاوز"},{"k":"li","t":"عند التقاطعات وممرات السكك الحديدية","b":false},{"k":"li","t":"عند معابر المشاة","b":false},{"k":"page","p":205},{"k":"p","t":"ممنوع التجاوز:","b":true},{"k":"li","t":"على الجسور","b":false},{"k":"li","t":"على الطرق المنحنية وفي المنحنيات الخطرة","b":false},{"k":"li","t":"على الطرق الزلقة","b":false},{"k":"page","p":206},{"k":"p","t":"ممنوع التجاوز:","b":true},{"k":"li","t":"عند نهاية الطرق الصاعدة","b":false},{"k":"li","t":"في الاتجاه المعاكس للمركبات الأخرى","b":false},{"k":"page","p":207},{"k":"p","t":"ممنوع التجاوز:","b":true},{"k":"li","t":"في الحالات التي تكون فيها الرؤية على الطرق غير كافية أو ضعيفة","b":false},{"k":"page","p":208},{"k":"p","t":"ممنوع التجاوز:","b":true},{"k":"li","t":"عندما تكون هناك إشارة مرور تشير إلى «ممنوع التجاوز»","b":false},{"k":"li","t":"عندما تكون هناك خطوط متصلة بين المسارات","b":false},{"k":"page","p":209},{"k":"p","t":"ممنوع التجاوز:","b":true},{"k":"li","t":"عندما لا تستطيع القيادة (بشكل ملحوظ) بشكل أسرع من المركبة التي تسير أمامك","b":false},{"k":"li","t":"في حالة تجاوز الحد الأقصى للسرعة","b":false},{"k":"li","t":"في حال بدأت مركبة أمامك بتجاوز مركبة أخرى أمامها","b":false},{"k":"li","t":"في حال بدأت مركبة خلفك بتجاوز مركبتك","b":false},{"k":"remember","t":" كما ترى هناك الكثير من الأشياء التي يجب مراعاتها عند التجاوز. لذلك تذكر بأن لا تحاول تجاوز مركبة أخرى إذا كانت لديك شكوك."}]},{"id":"hb-safeovertake","title":"متطلبات التجاوز بأمان","from":210,"to":210,"b":[{"k":"page","p":210},{"k":"h2","t":"4. متطلبات التجاوز بأمان"},{"k":"h3","t":"قبل التجاوز"},{"k":"li","t":"1. تحقق من سرعتك، فأنت بحاجة إلى فرق مناسب في السرعة مقارنة بسرعة المركبة التي تحاول تجاوزها (الفرق الجيد: فرق لا يقل عن 20 كم / ساعة) لكن لا تتجاوز الحد الأقصى للسرعة","b":false},{"k":"li","t":"2. تحقق من المساحة بجوار المركبة التي تريد تجاوزها، فأنت تحتاج إلى الحفاظ على مسافة جانبية آمنة وتأكد من أن المركبة أمامك لا تبدأ بالتجاوز عن مركبة أخرى.","b":false},{"k":"li","t":"3. تحقق من المرايا وانظر بجانب كتفك للتأكد من عدم تجاوزك من قبل مركبة أخرى.","b":false},{"k":"li","t":"4. تحقق من الطريق أمامك، بحيث لا تعيق حركة المرور القادمة ويجب أن تكون قادرا على تجاوز المركبة دون أي خطر وشيك (بدون منحنيات أو معابر أو عوائق أو ما إلى ذلك)","b":false},{"k":"li","t":"5. تأكد من وجود مساحة في الجانب الأيمن من الطريق للعودة إليه بعد الانتهاء من تجاوز المركبة أمامك.","b":false}]},{"id":"hb-overtakeissue","title":"مسألة التجاوز","from":211,"to":213,"b":[{"k":"page","p":211},{"k":"h2","t":"5. مسألة التجاوز"},{"k":"p","t":"قارن مسألة التجاوز بمسألة المرور عن الأشياء الثابتة.","b":true},{"k":"p","t":"ما هو الفرق؟ لماذا يمكن أن يكون التجاوز أكثر خطورة؟","b":false},{"k":"page","p":212},{"k":"h3","t":"قبل التجاوز"},{"k":"p","t":"انظر (Look): السرعة؟ الطريق أمامك؟ المساحة للعودة إلى المسار الأيمن؟","b":true},{"k":"p","t":"قيم (Assess): هل التجاوز مسموح به؟ هل هو آمن؟ قرر (Decide): قرر ما إذا أردت التجاوز أو البقاء في الخلف ضمن مسافة آمنة تصرف (Act): وفقا لقرارك: إما أن تقوم بالتجاوز (ابدأ MSSSM) أو تبطء سرعتك","b":true},{"k":"h3","t":"كيفية تجاوز مركبة تقود أمامك:"},{"k":"p","t":"المرايا (Mirrors): تحقق من المرآة الجانبية واليسرى لتشاهد المركبات خلفك (لأنها قد تبدأ بالتجاوز عنك)","b":true},{"k":"p","t":"الإشارة (Signal): قم بإعطاء إشارة لليسار الكتف (Shoulder): تحقق من النقطة العمياء على الجانب الأيسر للمركبات المجاورة لمركبتك","b":true},{"k":"p","t":"السرعة (Speed): تسريع (تجاوز السرعة في أسرع وقت ممكن دون تجاوز حد السرعة) التحرك (Move): الانتقال إلى الجانب الأيسر. تأكد من ترك مسافة جانبية كافية للمركبة التي تتجاوز عنها ومن ثم قم بالقيادة بسلاسة! العودة إلى المسار الأيمن: قم بإعطاء إشارة لليمين عندما يمكنك مشاهدة المركبة التي تجاوزت عنها في المرآة الداخلية، وقم بالقيادة بسلاسة!","b":true},{"k":"page","p":213},{"k":"p","t":"تأكد من القيام بكافة الاستعدادات والإجراءات للتجاوز الآمن – في حالة الشك، يجب تنبيه المركبة التي أمامك من خلال إشارة تحذير قبل البدء في التجاوز.","b":false},{"k":"p","t":"إشارات التحذير:","b":true},{"k":"li","t":"استخدام المنبه","b":false},{"k":"li","t":"استخدم الضوء الأمامي المتقطع","b":false}]},{"id":"hb-stopping","title":"إيقاف المركبة","from":214,"to":222,"b":[{"k":"page","p":214},{"k":"h2","t":"6. إيقاف المركبة"},{"k":"p","t":"استخدام أضواء المركبة والإشارات","b":true},{"k":"li","t":"مصابيح لوحة القيادة","b":false},{"k":"li","t":"رؤية واضحة","b":false},{"k":"p","t":"ايقاف المركبة","b":true},{"k":"li","t":"التوقف المؤقت","b":false},{"k":"li","t":"توقيف المركبة والاستمرار في الوقوف لفترة قصيرة ومحدودة.","b":false},{"k":"p","t":"الركن","b":true},{"k":"li","t":"إيقاف المركبة وتركها واقفة.","b":true},{"k":"page","p":215},{"k":"h3","t":"الإيقاف"},{"k":"p","t":"في الأماكن التي يسمح فيها بإيقاف المركبات، يتم ركن المركبة إما على جانب الطريق أو على جانب الرصيف الموازي لها إلا إذا كانت هناك إشارة تشير إلى إمكانية الإيقاف بطريقة أخرى.","b":false},{"k":"li","t":"بالتوازي مع جانب الطريق أو على جانب الرصيف الموازي له","b":false},{"k":"li","t":"بطريقة أخرى إذا كانت هناك إشارة تشير إلى ذلك","b":false},{"k":"page","p":216},{"k":"h3","t":"محددات إيقاف المركبة"},{"k":"p","t":"إشارات المرور تفيد هذه الإشارة أن إيقاف المركبة ممنوع وينتهي المنع عند أول منعطف بعد الإشارة، ويتم طلاء هذه المنطقة باللون الأصفر.","b":true},{"k":"li","t":"تعني هذه الإشارة: مسموح الانتظار وممنوع الوقوف","b":false},{"k":"li","t":"تعني هذه الإشارة: ممنوع الوقوف والانتظار","b":false},{"k":"page","p":217},{"k":"h3","t":"محددات إيقاف المركبة"},{"k":"li","t":"في الشوارع العامة، يتم طلاء منطقة إيقاف المركبات باللون الأصفر","b":false},{"k":"li","t":"في حال كانت الخطوط بيضاء، فيعني ذلك أنه لا توجد أي قيود على إيقاف المركبات","b":false},{"k":"page","p":218},{"k":"h3","t":"محددات إيقاف المركبة"},{"k":"li","t":"ممنوع إيقاف المركبة على معابر المشاة وعلى رصيف المشاة وأقل من متر ونصف من مكان عبور طلاب المدارس","b":false},{"k":"page","p":219},{"k":"h3","t":"محددات إيقاف المركبة"},{"k":"li","t":"ممنوع إيقاف المركبة على بعد 20 متر أو أقل من الأنفاق وعلى بعد 20 متر أو أقل من الجسور وعلى الجسور","b":false},{"k":"h3","t":"محددات إيقاف المركبة"},{"k":"li","t":"ممنوع إيقاف المركبات في أي منعطف","b":false},{"k":"li","t":"على رأس الطريق","b":false},{"k":"li","t":"في مفترق الطرق","b":false},{"k":"li","t":"على الرصيف","b":false},{"k":"li","t":"الكراج","b":false},{"k":"page","p":220},{"k":"h3","t":"ممنوع إيقاف المركبة عند التقاطعات"},{"k":"li","t":"على مسافة أقل من 15 مترا من إشارة ضوئية","b":false},{"k":"li","t":"على مسافة أقل من 15 مترا من منعطف","b":false},{"k":"page","p":221},{"k":"h3","t":"ممنوع إيقاف المركبة"},{"k":"li","t":"على مسافة أقل من 7 أمتار من صنبور مياه الحريق","b":false},{"k":"li","t":"أمام المداخل أو المخارج","b":false},{"k":"li","t":"ممنوع إيقاف المركبة في الأماكن المخصصة لفئة معينة من المركبات","b":false},{"k":"page","p":222},{"k":"h3","t":"ممنوع إيقاف المركبة"},{"k":"li","t":"في الاتجاه المعاكس لحركة السير","b":false},{"k":"li","t":"في وسط الطريق في حال تعطلت مركبة على الطرق السريعة، فيجب إيقافها بعيدا عن الطريق، إن أمكن. أما في النهار، فيجب أن تكون المركبة المعطلة مزودة بإشارات تحذير مرئية بشكل جيد. وأثناء الليل يجب أن توضع عليها أضواء حمراء لتجنب التصادم مع المركبات الأخرى.","b":false},{"k":"li","t":"على الطرق العامة خارج المدينة، إذا كانت المركبات المتوقفة تشكل خطرا على السلامة العامة","b":false}]},{"id":"hb-vlights","title":"استخدام مصابيح المركبة","from":223,"to":234,"b":[{"k":"page","p":223},{"k":"h2","t":"7. استخدام مصابيح المركبة"},{"k":"h3","t":"المصابيح الأمامية (تصدر أضواءا بيضاء)"},{"k":"li","t":"أضواء التموضع (أضواء توقف المركبة)","b":false},{"k":"li","t":"الأضواء المنخفضة (أضواء التلاقي بمركبة أخرى)","b":false},{"k":"li","t":"الأضواء العالية","b":false},{"k":"li","t":"المصابيح الخاصة بالضباب (في بعض المركبات فقط)","b":false},{"k":"page","p":224},{"k":"p","t":"المصابيح الخلفية","b":true},{"k":"li","t":"المصابيح الخلفية التي تصدر ضوءا أحمر","b":false},{"k":"li","t":"المصباح الخلفي الخاص بالضباب","b":false},{"k":"li","t":"مصابيح الفرامل (مصابيح التوقف)","b":false},{"k":"p","t":"تصدر ضوءا أبيض","b":true},{"k":"li","t":"مصابيح الرجوع للخلف (فقط عندما يكون ناقل الحركة في وضعية الرجوع «R»)","b":false},{"k":"li","t":"مصابيح لوحة الأرقام","b":false},{"k":"page","p":225},{"k":"h3","t":"لماذا من المهم استخدام مصابيح المركبة؟"},{"k":"p","t":"لأنك تريد أن تري كل شيء بشكل جيد في الليل وتريد أيضا أن يراك الآخرون، أليس كذلك؟","b":true},{"k":"page","p":226},{"k":"h3","t":"قواعد استخدام مصابيح المركبة"},{"k":"li","t":"في الليل يجب على السائقين استخدام مصابيح المركبة أثناء القيادة ليالاعلى الطريق، بغض النظر عما إذا كانت الطريق مجهزة بإضاءة عامة أم لا.","b":true},{"k":"li","t":"خلال النهار يجب على السائقين استخدام مصابيح المركبة أثناء النهار في حال وجود ضباب كثيف أو عواصف رملية يحجب الرؤية.","b":true},{"k":"page","p":227},{"k":"h3","t":"مصابيح التموضع (إيقاف المركبة ) مع المصابيح الخلفية"},{"k":"page","p":228},{"k":"h3","t":"مصابيح منخفضة (مصابيح التقاء المركبات) مع المصابيح الخلفية"},{"k":"p","t":"يجب على السائقين استخدام المصابيح المنخفضة","b":true},{"k":"li","t":"عند القيادة على الطرق الرئيسية","b":false},{"k":"li","t":"في الحالات التي يحظر فيها استخدام المصابيح العالية، ولا توفر مصابيح التموضع رؤية كافية، لكن يجب أن يكون السائق قادرا على الرؤية بوضوح وبشكل بعيد أمامه.","b":false},{"k":"li","t":"عندما لا تكون مصابيح التموضع كافية للسماح لمستخدمي الطريق الآخرين برؤية المركبات في الوقت المناسب وعلى مسافة كافية","b":false},{"k":"li","t":"في حالة وجود مشاكل في الرؤية أو وجود الضباب ولم تكن المركبة مجهزة بمصابيح خاصة بالضباب","b":false},{"k":"page","p":229},{"k":"h3","t":"المصابيح العالية مع المصابيح الخلفية"},{"k":"remember","t":" إن المصابيح العالية سوف تزعج الآخرين! لذلك استخدم المصابيح العادية في حال وجود آخرين أمامك على الطريق!"},{"k":"page","p":230},{"k":"h3","t":"ممنوع استخدام المصابيح العالية"},{"k":"p","t":"داخل المدن","b":true},{"k":"li","t":"ضمن حدود المدينة، يجب على السائقين استخدام المصابيح العادية","b":false},{"k":"p","t":"على الطرق خارج المدينة","b":true},{"k":"li","t":"في حالة وجود مركبات أخرى في الجهة المقابلة، يجب على السائق إغلاق المصابيح العالية على مسافة كافية لتمكين سائق المركبة القادمة من متابعة مساره بسهولة دون أي خطر.","b":false},{"k":"li","t":"في حال كنت تقود مركبتك خلف مركبات أخرى بمسافة أقل من 50 متر","b":false},{"k":"li","t":"في جميع الحالات التي قد تسبب ازعاج كبير لمستعملي الطريق الآخرين","b":false},{"k":"li","t":"في جميع الحالات التي قد تسبب ازعاج كبير لمستخدمي ممر مائي أو سكة حديدية موازية للطريق.","b":false},{"k":"page","p":231},{"k":"h3","t":"المصابيح الخلفية مع ضوء الضباب الخلفي"},{"k":"p","t":"يجب استخدام مصابيح الضباب الخلفية فقط في حالة وجود ضباب أو تساقط للثلوج أو الأمطار الغزيرة.","b":false},{"k":"p","t":"تأكدي من أنها ليست ساطعة بشكل يؤذي الآخرين!","b":false},{"k":"remember","t":" أضواء الضباب الخلفية يمكن أن تكون ساطعة بشكل قوي، لذلك استخدمها فقط عندما لا تكون هناك مركبات تسير خلفك مباشرة!"},{"k":"page","p":232},{"k":"h3","t":"مصابيح أخرى"},{"k":"p","t":"أضواء الضباب الأمامية يجب على سائقي المركبات المزودة بمصابيح للضباب استخدام هذه الأضواء في حالة الضباب أو تساقط الثلوج أو الأمطار الغزيرة","b":true},{"k":"p","t":"المصابيح الخلفية (أضواء خلفية حمراء)","b":true},{"k":"li","t":"على الطرق التي لا يوجد بها إضاءة عامة في الليل","b":false},{"k":"li","t":"على الطرق التي لا يوجد بها إضاءة عامة خلال النهار عندما يكون هناك ضباب أو أمطار غزيرة أو عاصفة رملية","b":false},{"k":"p","t":"مصابيح الوميض يحظر استخدام مصابيح الوميض دون الحصول على إذن من إدارة المرور","b":true},{"k":"p","t":"أضواء أو أجهزة حمراء عاكسة يحظر استخدام المصابيح أو الأجهزة الحمراء العاكسة من منتصف المركبة إلى المقدمة","b":true},{"k":"p","t":"المصابيح البيضاء يحظر استخدام المصابيح البيضاء من منتصف المركبة إلى الخلف استثناء: الأضواء المستخدمة على لوحة الأرقام ومصابيح الرجوع للخلف","b":true},{"k":"p","t":"العاكس الثلاثي يجب على سائقي الشاحنات وضع عاكس ثلاثي واحد أو أكثر (طول كل جانب 30 سم) على الطريق خلف الشاحنة وعلى الجانب الأيسر من الشاحنة في حال إيقافها في الليل خارج المدينة على الطرق العامة","b":true},{"k":"page","p":233},{"k":"h3","t":"أضواء الإشارة"},{"k":"p","t":"أضواء الفرامل (أضواء التوقف) تظهر هذه الأضواء الحمراء الساطعة في كل مرة تقوم فيها بالضغط على دواسة الفرامل","b":true},{"k":"p","t":"أضواء الرجوع للخلف تظهر هذه الأضواء البيضاء في حال القيادة إلى الخلف","b":true},{"k":"remember","t":" أضواء الإشارة مهمة للتواصل مع مستعملي الطريق الآخرين!"},{"k":"page","p":234},{"k":"h3","t":"أضواء الإشارة"},{"k":"p","t":"إشارة الإنعطاف (وامض/ غماز) في كل مرة تقوم فيها بتشغيل الوامض، تظهر لك الألوان الصفراء الثلاثة الخاصة بإشارة الإنعطاف.","b":true},{"k":"p","t":"أضواء التحذير من المخاطر (وامض / غماز) يوجد في المركبة 6 أضواء للتحذير من الخطر.","b":true}]},{"id":"hb-dash","title":"أضواء لوحة القيادة","from":235,"to":236,"b":[{"k":"page","p":235},{"k":"h2","t":"8. أضواء لوحة القيادة"},{"k":"p","t":"مصباح التحكم الأحمر يعني: عليك التوقف فورا! قم بإلقاء نظرة على دليل المركبة الخاص بك.","b":true},{"k":"p","t":"مصباح التحكم الأصفر يعني: هناك شئ غير صحيح. قم بفحص المركبة في أقرب وقت ممكن ولا تتجاهل الأمر لفترة طويلة!","b":true},{"k":"p","t":"مصباح التحكم الأخضر يعني: يخبرك انه كل شيء على مايرام.","b":true},{"k":"page","p":236},{"k":"h3","t":"مؤشر الوقود"},{"k":"p","t":"هذا هو مؤشر الوقود الخاص بك، حيث يظهر لك مقدار الوقود الذي لا يزال في خزان الوقود. يجب أن تقوم بتعبئة خزان الوقود عندما يكون المؤشر على ربع الخزان وذلك تفاديا لإنتهاء الوقود وأنت على الطريق لأن ذلك يعرض حياتك وحياة الآخرين للخطر","b":false}]},{"id":"hb-vision","title":"رؤية واضحة","from":237,"to":239,"b":[{"k":"page","p":237},{"k":"h2","t":"9. رؤية واضحة"},{"k":"p","t":"المفتاح الأيسر: تعديل اتجاه المروحة","b":true},{"k":"p","t":"الزر المركزي: دوران الهواء داخل المركبة (على سبيل المثال عند القيادة في الأنفاق.)","b":true},{"k":"p","t":"المفتاح المركزي: تعديل شدة المروحة الزر المركزي تسخين النافذة الخلفية","b":true},{"k":"page","p":238},{"k":"p","t":"المفتاح الأيمن: تعديل درجة الحرارة","b":true},{"k":"p","t":"الزر المركزي: قيام مكيف الهواء بتنقية الهواء من بخار الماء","b":true},{"k":"remember","t":" للتخلص من الضباب على النافذة الأمامية، قم بتشغيل كافة المفاتيح في اتجاه عقارب الساعة إلى أقصى اليمين!"},{"k":"page","p":239},{"k":"h2","t":"نتمنى لكم"},{"k":"h2","t":"قيادة آمنة"}]}];
